    { const char * tb_v398 = "// экран 80×25: байт буквы и байт цвета; русские буквы рисуем своим шрифтом (см. tb_vga_font)\n"; *(const char * *)tb_grow(v_lines) = tb_v398; }
    { const char * tb_v399 = "TB_API volatile unsigned short *const tb_vga = (volatile unsigned short *)0xB8000;\n"; *(const char * *)tb_grow(v_lines) = tb_v399; }
    { const char * tb_v400 = "TB_API int tb_vrow = 0, tb_vcol = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v400; }
