    { const char * tb_v1166 = "// «узких» функций (fopen, mkdir, getenv...) берёт кодовую страницу ANSI, и русские\n"; *(const char * *)tb_grow(v_lines) = tb_v1166; }
    { const char * tb_v1167 = "// имена ломаются. Поэтому здесь свои обёртки через «широкие» функции (_wfopen...),\n"; *(const char * *)tb_grow(v_lines) = tb_v1167; }
    { const char * tb_v1168 = "// а имена POSIX ниже подменяются на них — код библиотеки остаётся одним на все системы.\n"; *(const char * *)tb_grow(v_lines) = tb_v1168; }
