    { const char * tb_v1216 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v1216; }
    { const char * tb_v1217 = "TB_API int tb_win_mkdir(const char *path) { wchar_t *p = tb_wide(path); int r = p ? _wmkdir(p) : -1; free(p); return r; }\n"; *(const char * *)tb_grow(v_lines) = tb_v1217; }
    { const char * tb_v1218 = "TB_API int tb_win_rmdir(const char *path) { wchar_t *p = tb_wide(path); int r = p ? _wrmdir(p) : -1; free(p); return r; }\n"; *(const char * *)tb_grow(v_lines) = tb_v1218; }
    { const char * tb_v1219 = "TB_API int tb_win_unlink(const char *path) { wchar_t *p = tb_wide(path); int r = p ? _wunlink(p) : -1; free(p); return r; }\n"; *(const char * *)tb_grow(v_lines) = tb_v1219; }
    { const char * tb_v1220 = "// как в POSIX: файл на месте назначения заменяется (обычный rename на Windows так не умеет)\n"; *(const char * *)tb_grow(v_lines) = tb_v1220; }
    { const char * tb_v1221 = "TB_API int tb_win_rename(const char *from, const char *to) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1221; }
    { const char * tb_v1222 = "    wchar_t *a = tb_wide(from), *b = tb_wide(to);\n"; *(const char * *)tb_grow(v_lines) = tb_v1222; }
