    { const char * tb_v1240 = "// поэтому команда целиком берётся ещё в одни кавычки\n"; *(const char * *)tb_grow(v_lines) = tb_v1240; }
    { const char * tb_v1241 = "TB_API wchar_t *tb_win_cmd(const char *command) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1241; }
    { const char * tb_v1242 = "    size_t n = strlen(command);\n"; *(const char * *)tb_grow(v_lines) = tb_v1242; }
