    { const char * tb_v1342 = "#ifndef TB_BARE\n"; *(const char * *)tb_grow(v_lines) = tb_v1342; }
    { const char * tb_v1343 = "// ---------- падение по памяти: понятное сообщение вместо «Segmentation fault» ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v1343; }
    { const char * tb_v1344 = "// Чаще всего это стек: функция зовёт себя слишком глубоко. Обработчик работает\n"; *(const char * *)tb_grow(v_lines) = tb_v1344; }
    { const char * tb_v1345 = "// на своём маленьком стеке (sigaltstack), потому что основной уже кончился.\n"; *(const char * *)tb_grow(v_lines) = tb_v1345; }
    { const char * tb_v1346 = "#ifndef _WIN32\n"; *(const char * *)tb_grow(v_lines) = tb_v1346; }
