    { const char * tb_v1497 = "    sigaltstack(&ss, 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v1497; }
    { const char * tb_v1498 = "    struct sigaction sa;\n"; *(const char * *)tb_grow(v_lines) = tb_v1498; }
