    { const char * tb_v2138 = "    tb_list *l = tb_mem(sizeof(tb_list));\n"; *(const char * *)tb_grow(v_lines) = tb_v2138; }
    { const char * tb_v2139 = "    long long words = (n + 63) / 64 + (n == 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v2139; }
    { const char * tb_v2140 = "    l->len = n; l->cap = words * 64; l->size = 0; l->data = tb_mem_np(words * 8);\n"; *(const char * *)tb_grow(v_lines) = tb_v2140; }
