    { const char * tb_v2174 = "// N одинаковых битов в конец (repeat N times: flags.add(true))\n"; *(const char * *)tb_grow(v_lines) = tb_v2174; }
    { const char * tb_v2175 = "TB_API void tb_bfill(tb_list *l, long long n, _Bool v) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2175; }
    { const char * tb_v2176 = "    if (n <= 0) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v2176; }
    { const char * tb_v2177 = "    if (l->cap < 0) tb_crash(0, \"список нельзя растить, пока по нему идёт each ... by N (и сам кусок растить нельзя)\");\n"; *(const char * *)tb_grow(v_lines) = tb_v2177; }
    { const char * tb_v2178 = "    long long need = l->len + n;\n"; *(const char * *)tb_grow(v_lines) = tb_v2178; }
    { const char * tb_v2179 = "    if (need > l->cap) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2179; }
