    { const char * tb_v2568 = "// ---------- http_get: страница из интернета через curl (есть на Mac и почти на любом Linux) ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v2568; }
    { const char * tb_v2569 = "TB_API const char *tb_http_get(const char *url) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2569; }
    { const char * tb_v2570 = "    if (strncmp(url, \"http://\", 7) != 0 && strncmp(url, \"https://\", 8) != 0) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2570; }
    { const char * tb_v2571 = "        tb_err = tb_cat(\"адрес должен начинаться с http:// или https://: \", url);\n"; *(const char * *)tb_grow(v_lines) = tb_v2571; }
    { const char * tb_v2572 = "        return \"\";\n"; *(const char * *)tb_grow(v_lines) = tb_v2572; }
    { const char * tb_v2573 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v2573; }
    { const char * tb_v2574 = "    // адрес — в одинарных кавычках для shell: ' внутри адреса пишется как '\\''\n"; *(const char * *)tb_grow(v_lines) = tb_v2574; }
    { const char * tb_v2575 = "    size_t n = strlen(url);\n"; *(const char * *)tb_grow(v_lines) = tb_v2575; }
    { const char * tb_v2576 = "    char *cmd = malloc(n * 4 + 80);\n"; *(const char * *)tb_grow(v_lines) = tb_v2576; }
    { const char * tb_v2577 = "    if (!cmd) { tb_err = \"не хватило памяти\"; return \"\"; }\n"; *(const char * *)tb_grow(v_lines) = tb_v2577; }
    { const char * tb_v2578 = "#ifdef _WIN32\n"; *(const char * *)tb_grow(v_lines) = tb_v2578; }
    { const char * tb_v2579 = "    // curl.exe есть в Windows 10 и новее; адрес — в двойных кавычках для cmd.exe,\n"; *(const char * *)tb_grow(v_lines) = tb_v2579; }
    { const char * tb_v2580 = "    // (внутри кавычек & | < > ^ для cmd — простые знаки), а \" внутри адреса — как %22\n"; *(const char * *)tb_grow(v_lines) = tb_v2580; }
    { const char * tb_v2581 = "    size_t k = (size_t)sprintf(cmd, \"curl.exe -fsSL --max-time 30 \\\"\");\n"; *(const char * *)tb_grow(v_lines) = tb_v2581; }
    { const char * tb_v2582 = "    for (size_t i = 0; i < n; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2582; }
