    { const char * tb_v2584 = "        if (ch == '\"' || ch < 32) { sprintf(cmd + k, \"%%%02X\", ch); k += 3; }\n"; *(const char * *)tb_grow(v_lines) = tb_v2584; }
    { const char * tb_v2585 = "        else cmd[k++] = url[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v2585; }
    { const char * tb_v2586 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v2586; }
    { const char * tb_v2587 = "    strcpy(cmd + k, \"\\\" 2>NUL\");\n"; *(const char * *)tb_grow(v_lines) = tb_v2587; }
