    { const char * tb_v2589 = "#else\n"; *(const char * *)tb_grow(v_lines) = tb_v2589; }
    { const char * tb_v2590 = "    size_t k = (size_t)sprintf(cmd, \"curl -fsSL --max-time 30 '\");\n"; *(const char * *)tb_grow(v_lines) = tb_v2590; }
    { const char * tb_v2591 = "    for (size_t i = 0; i < n; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2591; }
    { const char * tb_v2592 = "        if (url[i] == '\\'') { memcpy(cmd + k, \"'\\\\''\", 4); k += 4; }\n"; *(const char * *)tb_grow(v_lines) = tb_v2592; }
    { const char * tb_v2593 = "        else cmd[k++] = url[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v2593; }
    { const char * tb_v2594 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v2594; }
