    { const char * tb_v2924 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2924; }
    { const char * tb_v2925 = "// --llvm: число ключей (из .ll не надо знать устройство tb_dict)\n"; *(const char * *)tb_grow(v_lines) = tb_v2925; }
    { const char * tb_v2926 = "TB_INL long long tb_dlen(tb_dict *d) { return d->keys->len; }\n"; *(const char * *)tb_grow(v_lines) = tb_v2926; }
