    { const char * tb_v2928 = "TB_INL tb_list *tb_dvals_copy(tb_dict *d) { return tb_copy(d->vals); }\n"; *(const char * *)tb_grow(v_lines) = tb_v2928; }
    { const char * tb_v2929 = "TB_API void tb_dclear(tb_dict *d, int line) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2929; }
