    { const char * tb_v2938 = "// новый ключ int k: можно ли остаться без поиска (mode 1 или 2)\n"; *(const char * *)tb_grow(v_lines) = tb_v2938; }
    { const char * tb_v2939 = "TB_API void tb_dplace_int(tb_dict *d, long long k) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2939; }
    { const char * tb_v2940 = "    long long n = d->keys->len;          // уже вместе с новым ключом\n"; *(const char * *)tb_grow(v_lines) = tb_v2940; }
    { const char * tb_v2941 = "    if (d->mode == 1) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2941; }
