    { const char * tb_v2958 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2958; }
    { const char * tb_v2959 = "// место под значение ключа k; если ключа нет — добавить со значением *def\n"; *(const char * *)tb_grow(v_lines) = tb_v2959; }
    { const char * tb_v2960 = "TB_API void *tb_dput(tb_dict *d, const void *k, const void *def) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2960; }
    { const char * tb_v2961 = "    long long at = tb_dfind(d, k);\n"; *(const char * *)tb_grow(v_lines) = tb_v2961; }
    { const char * tb_v2962 = "    if (at >= 0) return d->vals->data + at * d->vals->size;\n"; *(const char * *)tb_grow(v_lines) = tb_v2962; }
    { const char * tb_v2963 = "    memcpy(tb_grow(d->keys), k, d->keys->size);\n"; *(const char * *)tb_grow(v_lines) = tb_v2963; }
    { const char * tb_v2964 = "    void *v = tb_grow(d->vals);\n"; *(const char * *)tb_grow(v_lines) = tb_v2964; }
