    { const char * tb_v2977 = "    return v;\n"; *(const char * *)tb_grow(v_lines) = tb_v2977; }
    { const char * tb_v2978 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2978; }
    { const char * tb_v2979 = "TB_API void *tb_dget(tb_dict *d, const void *k, int line) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2979; }
