    { const char * tb_v3123 = "        if (!mine) continue;\n"; *(const char * *)tb_grow(v_lines) = tb_v3123; }
    { const char * tb_v3124 = "        work(job);\n"; *(const char * *)tb_grow(v_lines) = tb_v3124; }
