    { const char * tb_v3126 = "        if (__atomic_sub_fetch(&tb_pool_left, 1, __ATOMIC_ACQ_REL) == 0) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3126; }
    { const char * tb_v3127 = "            pthread_mutex_lock(&tb_pool_m);\n"; *(const char * *)tb_grow(v_lines) = tb_v3127; }
