    { const char * tb_v3139 = "    // пул уже занят (цикл на ядрах из background или изнутри другого) — по-старому, своими потоками\n"; *(const char * *)tb_grow(v_lines) = tb_v3139; }
    { const char * tb_v3140 = "    if (__atomic_exchange_n(&tb_pool_busy, 1, __ATOMIC_ACQ_REL)) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3140; }
    { const char * tb_v3141 = "        pthread_t t[256];\n"; *(const char * *)tb_grow(v_lines) = tb_v3141; }
