    { const char * tb_v3160 = "    pthread_mutex_unlock(&tb_pool_m);\n"; *(const char * *)tb_grow(v_lines) = tb_v3160; }
    { const char * tb_v3161 = "    work(job);\n"; *(const char * *)tb_grow(v_lines) = tb_v3161; }
    { const char * tb_v3162 = "    if (__atomic_load_n(&tb_pool_left, __ATOMIC_ACQUIRE) != 0) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3162; }
    { const char * tb_v3163 = "        for (int spin = 0; spin < 20000 && __atomic_load_n(&tb_pool_left, __ATOMIC_ACQUIRE) != 0; spin++)\n"; *(const char * *)tb_grow(v_lines) = tb_v3163; }
    { const char * tb_v3164 = "            __builtin_ia32_pause_or_yield();\n"; *(const char * *)tb_grow(v_lines) = tb_v3164; }
    { const char * tb_v3165 = "        pthread_mutex_lock(&tb_pool_m);\n"; *(const char * *)tb_grow(v_lines) = tb_v3165; }
    { const char * tb_v3166 = "        while (__atomic_load_n(&tb_pool_left, __ATOMIC_ACQUIRE) != 0) pthread_cond_wait(&tb_pool_end, &tb_pool_m);\n"; *(const char * *)tb_grow(v_lines) = tb_v3166; }
    { const char * tb_v3167 = "        pthread_mutex_unlock(&tb_pool_m);\n"; *(const char * *)tb_grow(v_lines) = tb_v3167; }
    { const char * tb_v3168 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v3168; }
