    { const char * tb_v3197 = "        a.u = old; b.d = a.d + v; nw = b.u;\n"; *(const char * *)tb_grow(v_lines) = tb_v3197; }
    { const char * tb_v3198 = "    } while (!__atomic_compare_exchange_n(q, &old, nw, 0, __ATOMIC_SEQ_CST, __ATOMIC_SEQ_CST));\n"; *(const char * *)tb_grow(v_lines) = tb_v3198; }
    { const char * tb_v3199 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3199; }
