    { const char * tb_v3361 = "// copy_mem(куда, откуда, байт): блоки могут перекрываться\n"; *(const char * *)tb_grow(v_lines) = tb_v3361; }
    { const char * tb_v3362 = "TB_API void tb_copy_mem(long long dst, long long src, long long n, int line) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3362; }
    { const char * tb_v3363 = "    if (n < 0) tb_crash(line, \"copy_mem: число байт меньше нуля\");\n"; *(const char * *)tb_grow(v_lines) = tb_v3363; }
