    { const char * tb_v3374 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v3374; }
    { const char * tb_v3375 = "// текст из C: копия в память Tachbit (C может потом поменять или отдать свой); NULL → \"\"\n"; *(const char * *)tb_grow(v_lines) = tb_v3375; }
    { const char * tb_v3376 = "TB_API const char *tb_ctext(const char *p) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3376; }
    { const char * tb_v3377 = "    if (!p) return \"\";\n"; *(const char * *)tb_grow(v_lines) = tb_v3377; }
    { const char * tb_v3378 = "    size_t n = strlen(p);\n"; *(const char * *)tb_grow(v_lines) = tb_v3378; }
    { const char * tb_v3379 = "    char *s = tb_tmem(n + 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v3379; }
    { const char * tb_v3380 = "    memcpy(s, p, n + 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v3380; }
    { const char * tb_v3381 = "    return s;\n"; *(const char * *)tb_grow(v_lines) = tb_v3381; }
    { const char * tb_v3382 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3382; }
    { const char * tb_v3383 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v3383; }
    { const char * tb_v3384 = "// ---------- zone: область памяти. Много кусков берутся быстро и освобождаются разом ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v3384; }
    { const char * tb_v3385 = "// Зона — цепочка больших кусков. zone_take отрезает от текущего куска (16 байт выравнивание, нули),\n"; *(const char * *)tb_grow(v_lines) = tb_v3385; }
    { const char * tb_v3386 = "// кончился кусок — берёт новый. zone_clear отдаёт всё, кроме первого куска; zone_free — всё.\n"; *(const char * *)tb_grow(v_lines) = tb_v3386; }
    { const char * tb_v3387 = "#define TB_ZONE_LIVE 0x5A4F4E454C495645ULL\n"; *(const char * *)tb_grow(v_lines) = tb_v3387; }
    { const char * tb_v3388 = "typedef struct tb_zchunk { struct tb_zchunk *next; uint64_t size, used, pad; } tb_zchunk;   // 32 байта: данные с выравниванием 16\n"; *(const char * *)tb_grow(v_lines) = tb_v3388; }
    { const char * tb_v3389 = "typedef struct { uint64_t magic, step; tb_zchunk *first, *cur; } tb_zone;\n"; *(const char * *)tb_grow(v_lines) = tb_v3389; }
    { const char * tb_v3390 = "// данные куска: сразу за заголовком, с выравниванием 16 (malloc в ядре выравнивает меньше)\n"; *(const char * *)tb_grow(v_lines) = tb_v3390; }
    { const char * tb_v3391 = "#define TB_ZDATA(k) ((unsigned char *)(((uintptr_t)((k) + 1) + 15) & ~(uintptr_t)15))\n"; *(const char * *)tb_grow(v_lines) = tb_v3391; }
    { const char * tb_v3392 = "static tb_zchunk *tb_zone_chunk(uint64_t n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3392; }
    { const char * tb_v3393 = "    tb_zchunk *k = malloc(sizeof(tb_zchunk) + (size_t)n + 16);\n"; *(const char * *)tb_grow(v_lines) = tb_v3393; }
    { const char * tb_v3394 = "    if (!k) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3394; }
    { const char * tb_v3395 = "    k->next = 0; k->size = n; k->used = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3395; }
    { const char * tb_v3396 = "    memset(TB_ZDATA(k), 0, (size_t)n);\n"; *(const char * *)tb_grow(v_lines) = tb_v3396; }
    { const char * tb_v3397 = "    return k;\n"; *(const char * *)tb_grow(v_lines) = tb_v3397; }
    { const char * tb_v3398 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3398; }
    { const char * tb_v3399 = "// zone_new(байт): первый кусок такого размера; дальше куски того же размера (или больше, если нужно)\n"; *(const char * *)tb_grow(v_lines) = tb_v3399; }
    { const char * tb_v3400 = "TB_API long long tb_zone_new(long long n, int line) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3400; }
    { const char * tb_v3401 = "    (void)line;\n"; *(const char * *)tb_grow(v_lines) = tb_v3401; }
    { const char * tb_v3402 = "    if (n <= 0) { tb_err = \"zone_new: размер должен быть больше нуля\"; return 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3402; }
    { const char * tb_v3403 = "    if ((unsigned long long)n > ((unsigned long long)1 << 46)) { tb_err = \"zone_new: слишком большой размер\"; return 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3403; }
    { const char * tb_v3404 = "    tb_zone *z = malloc(sizeof(tb_zone));\n"; *(const char * *)tb_grow(v_lines) = tb_v3404; }
    { const char * tb_v3405 = "    if (!z) { tb_err = \"zone_new: не хватило памяти\"; return 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3405; }
    { const char * tb_v3406 = "    uint64_t step = ((uint64_t)n + 15) & ~(uint64_t)15;\n"; *(const char * *)tb_grow(v_lines) = tb_v3406; }
    { const char * tb_v3407 = "    z->first = z->cur = tb_zone_chunk(step);\n"; *(const char * *)tb_grow(v_lines) = tb_v3407; }
    { const char * tb_v3408 = "    if (!z->first) { free(z); tb_err = \"zone_new: не хватило памяти\"; return 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3408; }
    { const char * tb_v3409 = "    z->magic = TB_ZONE_LIVE; z->step = step;\n"; *(const char * *)tb_grow(v_lines) = tb_v3409; }
    { const char * tb_v3410 = "    return (long long)(uintptr_t)z;\n"; *(const char * *)tb_grow(v_lines) = tb_v3410; }
    { const char * tb_v3411 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3411; }
    { const char * tb_v3412 = "static tb_zone *tb_zone_own(long long a, int line, const char *who) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3412; }
    { const char * tb_v3413 = "    tb_zone *z = (tb_zone *)(uintptr_t)a;\n"; *(const char * *)tb_grow(v_lines) = tb_v3413; }
    { const char * tb_v3414 = "    if (!z || z->magic != TB_ZONE_LIVE) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3414; }
    { const char * tb_v3415 = "        char buf[120];\n"; *(const char * *)tb_grow(v_lines) = tb_v3415; }
    { const char * tb_v3416 = "        snprintf(buf, sizeof buf, \"%s: это не зона из zone_new или она уже освобождена\", who);\n"; *(const char * *)tb_grow(v_lines) = tb_v3416; }
    { const char * tb_v3417 = "        tb_crash(line, buf);\n"; *(const char * *)tb_grow(v_lines) = tb_v3417; }
    { const char * tb_v3418 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v3418; }
    { const char * tb_v3419 = "    return z;\n"; *(const char * *)tb_grow(v_lines) = tb_v3419; }
    { const char * tb_v3420 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3420; }
    { const char * tb_v3421 = "// zone_take(зона, байт): адрес нового куска (нули)\n"; *(const char * *)tb_grow(v_lines) = tb_v3421; }
    { const char * tb_v3422 = "TB_API long long tb_zone_take(long long a, long long n, int line) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3422; }
    { const char * tb_v3423 = "    tb_zone *z = tb_zone_own(a, line, \"zone_take\");\n"; *(const char * *)tb_grow(v_lines) = tb_v3423; }
    { const char * tb_v3424 = "    if (n <= 0) tb_crash(line, \"zone_take: размер должен быть больше нуля\");\n"; *(const char * *)tb_grow(v_lines) = tb_v3424; }
    { const char * tb_v3425 = "    uint64_t need = ((uint64_t)n + 15) & ~(uint64_t)15;\n"; *(const char * *)tb_grow(v_lines) = tb_v3425; }
    { const char * tb_v3426 = "    tb_zchunk *k = z->cur;\n"; *(const char * *)tb_grow(v_lines) = tb_v3426; }
    { const char * tb_v3427 = "    if (k->size - k->used < need) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3427; }
    { const char * tb_v3428 = "        if (k->next && k->next->size >= need) k = k->next;\n"; *(const char * *)tb_grow(v_lines) = tb_v3428; }
    { const char * tb_v3429 = "        else {\n"; *(const char * *)tb_grow(v_lines) = tb_v3429; }
    { const char * tb_v3430 = "            tb_zchunk *nk = tb_zone_chunk(need > z->step ? need : z->step);\n"; *(const char * *)tb_grow(v_lines) = tb_v3430; }
    { const char * tb_v3431 = "            if (!nk) tb_crash(line, \"zone_take: не хватило памяти\");\n"; *(const char * *)tb_grow(v_lines) = tb_v3431; }
    { const char * tb_v3432 = "            nk->next = k->next; k->next = nk; k = nk;\n"; *(const char * *)tb_grow(v_lines) = tb_v3432; }
    { const char * tb_v3433 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v3433; }
    { const char * tb_v3434 = "        z->cur = k;\n"; *(const char * *)tb_grow(v_lines) = tb_v3434; }
    { const char * tb_v3435 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v3435; }
    { const char * tb_v3436 = "    unsigned char *p = TB_ZDATA(k) + k->used;\n"; *(const char * *)tb_grow(v_lines) = tb_v3436; }
    { const char * tb_v3437 = "    k->used += need;\n"; *(const char * *)tb_grow(v_lines) = tb_v3437; }
    { const char * tb_v3438 = "    return (long long)(uintptr_t)p;\n"; *(const char * *)tb_grow(v_lines) = tb_v3438; }
    { const char * tb_v3439 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3439; }
    { const char * tb_v3440 = "// zone_clear(зона): всё взятое больше не нужно; первый кусок остаётся для новых zone_take\n"; *(const char * *)tb_grow(v_lines) = tb_v3440; }
    { const char * tb_v3441 = "TB_API void tb_zone_clear(long long a, int line) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3441; }
    { const char * tb_v3442 = "    tb_zone *z = tb_zone_own(a, line, \"zone_clear\");\n"; *(const char * *)tb_grow(v_lines) = tb_v3442; }
    { const char * tb_v3443 = "    tb_zchunk *k = z->first->next;\n"; *(const char * *)tb_grow(v_lines) = tb_v3443; }
    { const char * tb_v3444 = "    while (k) { tb_zchunk *nx = k->next; free(k); k = nx; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3444; }
    { const char * tb_v3445 = "    z->first->next = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3445; }
    { const char * tb_v3446 = "    memset(TB_ZDATA(z->first), 0, (size_t)z->first->used);\n"; *(const char * *)tb_grow(v_lines) = tb_v3446; }
    { const char * tb_v3447 = "    z->first->used = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3447; }
    { const char * tb_v3448 = "    z->cur = z->first;\n"; *(const char * *)tb_grow(v_lines) = tb_v3448; }
    { const char * tb_v3449 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3449; }
    { const char * tb_v3450 = "// zone_free(зона): отдать всё; zone_free(0) ничего не делает\n"; *(const char * *)tb_grow(v_lines) = tb_v3450; }
    { const char * tb_v3451 = "TB_API void tb_zone_free(long long a, int line) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3451; }
    { const char * tb_v3452 = "    if (a == 0) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v3452; }
    { const char * tb_v3453 = "    tb_zone *z = tb_zone_own(a, line, \"zone_free\");\n"; *(const char * *)tb_grow(v_lines) = tb_v3453; }
    { const char * tb_v3454 = "    tb_zchunk *k = z->first;\n"; *(const char * *)tb_grow(v_lines) = tb_v3454; }
    { const char * tb_v3455 = "    while (k) { tb_zchunk *nx = k->next; free(k); k = nx; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3455; }
    { const char * tb_v3456 = "    z->magic = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3456; }
    { const char * tb_v3457 = "    free(z);\n"; *(const char * *)tb_grow(v_lines) = tb_v3457; }
    { const char * tb_v3458 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3458; }
    { const char * tb_v3459 = "// zone_used(зона): сколько байт взято (с выравниванием)\n"; *(const char * *)tb_grow(v_lines) = tb_v3459; }
    { const char * tb_v3460 = "TB_API long long tb_zone_used(long long a, int line) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3460; }
    { const char * tb_v3461 = "    tb_zone *z = tb_zone_own(a, line, \"zone_used\");\n"; *(const char * *)tb_grow(v_lines) = tb_v3461; }
    { const char * tb_v3462 = "    long long s = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3462; }
    { const char * tb_v3463 = "    for (tb_zchunk *k = z->first; k; k = k->next) s += (long long)k->used;\n"; *(const char * *)tb_grow(v_lines) = tb_v3463; }
    { const char * tb_v3464 = "    return s;\n"; *(const char * *)tb_grow(v_lines) = tb_v3464; }
    { const char * tb_v3465 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3465; }
    { const char * tb_v3466 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v3466; }
    { const char * tb_v3467 = "// ---------- syscall(номер, ...): прямой вызов ядра ОС (Linux, Mac). Ответ -1 → -номер ошибки ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v3467; }
    { const char * tb_v3468 = "#if !defined(TB_BARE) && !defined(_WIN32)\n"; *(const char * *)tb_grow(v_lines) = tb_v3468; }
    { const char * tb_v3469 = "#include <sys/syscall.h>\n"; *(const char * *)tb_grow(v_lines) = tb_v3469; }
    { const char * tb_v3470 = "#include <errno.h>\n"; *(const char * *)tb_grow(v_lines) = tb_v3470; }
    { const char * tb_v3471 = "#ifdef __APPLE__\n"; *(const char * *)tb_grow(v_lines) = tb_v3471; }
    { const char * tb_v3472 = "#pragma clang diagnostic push\n"; *(const char * *)tb_grow(v_lines) = tb_v3472; }
    { const char * tb_v3473 = "#pragma clang diagnostic ignored \"-Wdeprecated-declarations\"\n"; *(const char * *)tb_grow(v_lines) = tb_v3473; }
    { const char * tb_v3474 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v3474; }
    { const char * tb_v3475 = "TB_API long long tb_syscall(long long n, long long a, long long b, long long c, long long d, long long e, long long f, int line) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3475; }
    { const char * tb_v3476 = "    (void)line;\n"; *(const char * *)tb_grow(v_lines) = tb_v3476; }
    { const char * tb_v3477 = "    long r = syscall((long)n, (long)a, (long)b, (long)c, (long)d, (long)e, (long)f);\n"; *(const char * *)tb_grow(v_lines) = tb_v3477; }
    { const char * tb_v3478 = "    if (r == -1) return -(long long)errno;\n"; *(const char * *)tb_grow(v_lines) = tb_v3478; }
    { const char * tb_v3479 = "    return (long long)r;\n"; *(const char * *)tb_grow(v_lines) = tb_v3479; }
    { const char * tb_v3480 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3480; }
    { const char * tb_v3481 = "#ifdef __APPLE__\n"; *(const char * *)tb_grow(v_lines) = tb_v3481; }
    { const char * tb_v3482 = "#pragma clang diagnostic pop\n"; *(const char * *)tb_grow(v_lines) = tb_v3482; }
    { const char * tb_v3483 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v3483; }
    { const char * tb_v3484 = "#else\n"; *(const char * *)tb_grow(v_lines) = tb_v3484; }
    { const char * tb_v3485 = "TB_API long long tb_syscall(long long n, long long a, long long b, long long c, long long d, long long e, long long f, int line) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3485; }
    { const char * tb_v3486 = "    (void)n; (void)a; (void)b; (void)c; (void)d; (void)e; (void)f;\n"; *(const char * *)tb_grow(v_lines) = tb_v3486; }
    { const char * tb_v3487 = "    tb_crash(line, \"syscall есть только на Linux и Mac\");\n"; *(const char * *)tb_grow(v_lines) = tb_v3487; }
    { const char * tb_v3488 = "    return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3488; }
    { const char * tb_v3489 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3489; }
    { const char * tb_v3490 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v3490; }
    { const char * tb_v3491 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v3491; }
    { const char * tb_v3492 = "// ---------- shape: поля с размером прямо в памяти (регистры, заголовки пакетов) ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v3492; }
    { const char * tb_v3493 = "// k = смещение × 2^20 + байт (1, 2, 4, 8; 0 — bytes: отдать адрес) + 16 со знаком + 32 big\n"; *(const char * *)tb_grow(v_lines) = tb_v3493; }
    { const char * tb_v3494 = "//     + 64 × первый бит + 4096 × сколько бит (0 — поле целиком).\n"; *(const char * *)tb_grow(v_lines) = tb_v3494; }
    { const char * tb_v3495 = "// Поле читается и пишется одним volatile-доступом своей ширины: регистр u32 — одной 32-битной операцией.\n"; *(const char * *)tb_grow(v_lines) = tb_v3495; }
    { const char * tb_v3496 = "static inline uint64_t tb_shape_raw(uintptr_t p, int nb) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3496; }
    { const char * tb_v3497 = "    if (nb == 1) return *(volatile uint8_t *)p;\n"; *(const char * *)tb_grow(v_lines) = tb_v3497; }
    { const char * tb_v3498 = "    if (nb == 2) return *(volatile uint16_t *)p;\n"; *(const char * *)tb_grow(v_lines) = tb_v3498; }
    { const char * tb_v3499 = "    if (nb == 4) return *(volatile uint32_t *)p;\n"; *(const char * *)tb_grow(v_lines) = tb_v3499; }
    { const char * tb_v3500 = "    return *(volatile uint64_t *)p;\n"; *(const char * *)tb_grow(v_lines) = tb_v3500; }
    { const char * tb_v3501 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3501; }
    { const char * tb_v3502 = "static inline void tb_shape_put(uintptr_t p, int nb, uint64_t v) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3502; }
    { const char * tb_v3503 = "    if (nb == 1) *(volatile uint8_t *)p = (uint8_t)v;\n"; *(const char * *)tb_grow(v_lines) = tb_v3503; }
    { const char * tb_v3504 = "    else if (nb == 2) *(volatile uint16_t *)p = (uint16_t)v;\n"; *(const char * *)tb_grow(v_lines) = tb_v3504; }
