    { const char * tb_v4081 = "            int v = r[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v4081; }
    { const char * tb_v4082 = "            if (f == 1) v += a; else if (f == 2) v += b; else if (f == 3) v += (a + b) / 2; else if (f == 4) v += tb_paeth(a, b, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v4082; }
    { const char * tb_v4083 = "            r[i] = (unsigned char)v;\n"; *(const char * *)tb_grow(v_lines) = tb_v4083; }
    { const char * tb_v4084 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v4084; }
    { const char * tb_v4085 = "        prev = r;\n"; *(const char * *)tb_grow(v_lines) = tb_v4085; }
    { const char * tb_v4086 = "        for (unsigned x = 0; x < w; x++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4086; }
    { const char * tb_v4087 = "            unsigned s[4] = { 0, 0, 0, 255 }, raw[4] = { 0, 0, 0, 0 };\n"; *(const char * *)tb_grow(v_lines) = tb_v4087; }
    { const char * tb_v4088 = "            for (int k = 0; k < ch; k++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4088; }
    { const char * tb_v4089 = "                if (depth == 8) raw[k] = r[x * ch + k], s[k] = raw[k];\n"; *(const char * *)tb_grow(v_lines) = tb_v4089; }
    { const char * tb_v4090 = "                else if (depth == 16) raw[k] = ((unsigned)r[(x * ch + k) * 2] << 8) | r[(x * ch + k) * 2 + 1], s[k] = raw[k] >> 8;\n"; *(const char * *)tb_grow(v_lines) = tb_v4090; }
    { const char * tb_v4091 = "                else {\n"; *(const char * *)tb_grow(v_lines) = tb_v4091; }
    { const char * tb_v4092 = "                    unsigned bit = x * depth, v = (r[bit / 8] >> (8 - depth - bit % 8)) & ((1u << depth) - 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v4092; }
    { const char * tb_v4093 = "                    raw[k] = v; s[k] = ctype == 3 ? v : v * 255 / ((1u << depth) - 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v4093; }
    { const char * tb_v4094 = "                }\n"; *(const char * *)tb_grow(v_lines) = tb_v4094; }
    { const char * tb_v4095 = "            }\n"; *(const char * *)tb_grow(v_lines) = tb_v4095; }
    { const char * tb_v4096 = "            unsigned R, G, B, A;\n"; *(const char * *)tb_grow(v_lines) = tb_v4096; }
    { const char * tb_v4097 = "            if (ctype == 3) { unsigned i = s[0] < 256 ? s[0] : 0; R = pal[i][0]; G = pal[i][1]; B = pal[i][2]; A = pal[i][3]; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4097; }
    { const char * tb_v4098 = "            else if (ctype == 0 || ctype == 4) { R = G = B = s[0]; A = ctype == 4 ? s[1] : (trns && raw[0] == key[0] ? 0 : 255); }\n"; *(const char * *)tb_grow(v_lines) = tb_v4098; }
    { const char * tb_v4099 = "            else { R = s[0]; G = s[1]; B = s[2]; A = ctype == 6 ? s[3] : (trns && raw[0] == key[0] && raw[1] == key[1] && raw[2] == key[2] ? 0 : 255); }\n"; *(const char * *)tb_grow(v_lines) = tb_v4099; }
    { const char * tb_v4100 = "            px[(size_t)y * w + x] = (A << 24) | (R << 16) | (G << 8) | B;\n"; *(const char * *)tb_grow(v_lines) = tb_v4100; }
    { const char * tb_v4101 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v4101; }
    { const char * tb_v4102 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v4102; }
    { const char * tb_v4103 = "    free(z.out);\n"; *(const char * *)tb_grow(v_lines) = tb_v4103; }
    { const char * tb_v4104 = "    *pw = (int)w; *ph = (int)h;\n"; *(const char * *)tb_grow(v_lines) = tb_v4104; }
    { const char * tb_v4105 = "    return px;\n"; *(const char * *)tb_grow(v_lines) = tb_v4105; }
    { const char * tb_v4106 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v4106; }
    { const char * tb_v4107 = "// все картинки программы: точки подряд в одном большом массиве (его же видит видеокарта)\n"; *(const char * *)tb_grow(v_lines) = tb_v4107; }
    { const char * tb_v4108 = "typedef struct { int w, h; uint32_t off; } tb_image;\n"; *(const char * *)tb_grow(v_lines) = tb_v4108; }
    { const char * tb_v4109 = "TB_API tb_image *tb_imgs = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4109; }
    { const char * tb_v4110 = "TB_API int tb_nimg = 0, tb_img_dirty = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4110; }
    { const char * tb_v4111 = "TB_API uint32_t *tb_imgpx = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4111; }
    { const char * tb_v4112 = "TB_API size_t tb_imgpx_n = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4112; }
    { const char * tb_v4113 = "TB_API long long tb_load_image(const char *path) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4113; }
    { const char * tb_v4114 = "    FILE *f = fopen(path, \"rb\");\n"; *(const char * *)tb_grow(v_lines) = tb_v4114; }
    { const char * tb_v4115 = "    if (!f) { tb_err = \"нет такого файла картинки\"; return -1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4115; }
    { const char * tb_v4116 = "    fseek(f, 0, SEEK_END); long sz = ftell(f); fseek(f, 0, SEEK_SET);\n"; *(const char * *)tb_grow(v_lines) = tb_v4116; }
    { const char * tb_v4117 = "    unsigned char *d = sz > 0 ? malloc((size_t)sz) : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4117; }
    { const char * tb_v4118 = "    if (!d || fread(d, 1, (size_t)sz, f) != (size_t)sz) { fclose(f); free(d); tb_err = \"не могу прочитать файл картинки\"; return -1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4118; }
    { const char * tb_v4119 = "    fclose(f);\n"; *(const char * *)tb_grow(v_lines) = tb_v4119; }
    { const char * tb_v4120 = "    int w = 0, h = 0; const char *why = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4120; }
    { const char * tb_v4121 = "    uint32_t *px = tb_png(d, (size_t)sz, &w, &h, &why);\n"; *(const char * *)tb_grow(v_lines) = tb_v4121; }
    { const char * tb_v4122 = "    free(d);\n"; *(const char * *)tb_grow(v_lines) = tb_v4122; }
    { const char * tb_v4123 = "    if (!px) { tb_err = why; return -1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4123; }
    { const char * tb_v4124 = "    size_t need = tb_imgpx_n + (size_t)w * h;\n"; *(const char * *)tb_grow(v_lines) = tb_v4124; }
    { const char * tb_v4125 = "    if (need > 0xFFFFFFFFu) { free(px); tb_err = \"слишком много картинок\"; return -1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4125; }
    { const char * tb_v4126 = "    uint32_t *all = realloc(tb_imgpx, need * 4);\n"; *(const char * *)tb_grow(v_lines) = tb_v4126; }
    { const char * tb_v4127 = "    tb_image *list = realloc(tb_imgs, (size_t)(tb_nimg + 1) * sizeof(tb_image));\n"; *(const char * *)tb_grow(v_lines) = tb_v4127; }
    { const char * tb_v4128 = "    if (all) tb_imgpx = all;\n"; *(const char * *)tb_grow(v_lines) = tb_v4128; }
    { const char * tb_v4129 = "    if (list) tb_imgs = list;\n"; *(const char * *)tb_grow(v_lines) = tb_v4129; }
    { const char * tb_v4130 = "    if (!all || !list) { free(px); tb_err = \"не хватило памяти\"; return -1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4130; }
    { const char * tb_v4131 = "    memcpy(tb_imgpx + tb_imgpx_n, px, (size_t)w * h * 4);\n"; *(const char * *)tb_grow(v_lines) = tb_v4131; }
