    { const char * tb_v4133 = "    tb_imgs[tb_nimg].w = w; tb_imgs[tb_nimg].h = h; tb_imgs[tb_nimg].off = (uint32_t)tb_imgpx_n;\n"; *(const char * *)tb_grow(v_lines) = tb_v4133; }
    { const char * tb_v4134 = "    tb_imgpx_n = need;\n"; *(const char * *)tb_grow(v_lines) = tb_v4134; }
    { const char * tb_v4135 = "    tb_img_dirty = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v4135; }
    { const char * tb_v4136 = "    return tb_nimg++;\n"; *(const char * *)tb_grow(v_lines) = tb_v4136; }
    { const char * tb_v4137 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v4137; }
    { const char * tb_v4138 = "TB_API long long tb_image_w(long long i) { return i >= 0 && i < tb_nimg ? tb_imgs[i].w : 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4138; }
    { const char * tb_v4139 = "TB_API long long tb_image_h(long long i) { return i >= 0 && i < tb_nimg ? tb_imgs[i].h : 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4139; }
    { const char * tb_v4140 = "// ---------- шрифты TTF: свой чтец (таблицы glyf, без чужих библиотек) ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v4140; }
    { const char * tb_v4141 = "// Буква рисуется на процессоре один раз в маленькую картинку с прозрачностью (сглаживание),\n"; *(const char * *)tb_grow(v_lines) = tb_v4141; }
    { const char * tb_v4142 = "// дальше её рисуют и видеокарта, и процессор одинаково: точка = (цвет * a + фон * (255 - a)) / 255.\n"; *(const char * *)tb_grow(v_lines) = tb_v4142; }
    { const char * tb_v4143 = "typedef struct { unsigned char *d; size_t n; uint32_t glyf, loca, hmtx, cmap; int upem, locfmt, nglyphs, nhm, asc, desc, cfmt; } tb_font_t;\n"; *(const char * *)tb_grow(v_lines) = tb_v4143; }
    { const char * tb_v4144 = "TB_API tb_font_t *tb_fonts = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4144; }
    { const char * tb_v4145 = "TB_API int tb_nfonts = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4145; }
    { const char * tb_v4146 = "static unsigned tb_u16(const tb_font_t *f, size_t o) { return o + 2 <= f->n ? (unsigned)(f->d[o] << 8 | f->d[o + 1]) : 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4146; }
    { const char * tb_v4147 = "static int tb_s16(const tb_font_t *f, size_t o) { return (int16_t)tb_u16(f, o); }\n"; *(const char * *)tb_grow(v_lines) = tb_v4147; }
    { const char * tb_v4148 = "static uint32_t tb_u32(const tb_font_t *f, size_t o) { return o + 4 <= f->n ? ((uint32_t)f->d[o] << 24 | (uint32_t)f->d[o + 1] << 16 | (uint32_t)f->d[o + 2] << 8 | f->d[o + 3]) : 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4148; }
    { const char * tb_v4149 = "static uint32_t tb_ttf_table(const tb_font_t *f, size_t base, const char *tag) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4149; }
    { const char * tb_v4150 = "    unsigned n = tb_u16(f, base + 4);\n"; *(const char * *)tb_grow(v_lines) = tb_v4150; }
    { const char * tb_v4151 = "    for (unsigned i = 0; i < n; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4151; }
    { const char * tb_v4152 = "        size_t e = base + 12 + 16 * (size_t)i;\n"; *(const char * *)tb_grow(v_lines) = tb_v4152; }
    { const char * tb_v4153 = "        if (e + 16 <= f->n && memcmp(f->d + e, tag, 4) == 0) return tb_u32(f, e + 8);\n"; *(const char * *)tb_grow(v_lines) = tb_v4153; }
    { const char * tb_v4154 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v4154; }
    { const char * tb_v4155 = "    return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4155; }
    { const char * tb_v4156 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v4156; }
    { const char * tb_v4157 = "TB_API void tb_gpu_blend_probe(void);   // TB_GPU_CHECK: проба смешивания букв (ниже)\n"; *(const char * *)tb_grow(v_lines) = tb_v4157; }
    { const char * tb_v4158 = "TB_API long long tb_load_font(const char *path) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4158; }
    { const char * tb_v4159 = "    FILE *fp = fopen(path, \"rb\");\n"; *(const char * *)tb_grow(v_lines) = tb_v4159; }
    { const char * tb_v4160 = "    if (!fp) { tb_err = tb_cat(\"нет такого файла шрифта: \", path); return -1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4160; }
    { const char * tb_v4161 = "    fseek(fp, 0, SEEK_END); long sz = ftell(fp); fseek(fp, 0, SEEK_SET);\n"; *(const char * *)tb_grow(v_lines) = tb_v4161; }
    { const char * tb_v4162 = "    unsigned char *d = sz > 12 ? malloc((size_t)sz) : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4162; }
    { const char * tb_v4163 = "    if (!d || fread(d, 1, (size_t)sz, fp) != (size_t)sz) { fclose(fp); free(d); tb_err = \"не могу прочитать файл шрифта\"; return -1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4163; }
    { const char * tb_v4164 = "    fclose(fp);\n"; *(const char * *)tb_grow(v_lines) = tb_v4164; }
    { const char * tb_v4165 = "    tb_font_t f = { d, (size_t)sz };\n"; *(const char * *)tb_grow(v_lines) = tb_v4165; }
    { const char * tb_v4166 = "    size_t base = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4166; }
    { const char * tb_v4167 = "    if (memcmp(d, \"ttcf\", 4) == 0) base = tb_u32(&f, 12);   // сборник шрифтов (.ttc): берём первый\n"; *(const char * *)tb_grow(v_lines) = tb_v4167; }
    { const char * tb_v4168 = "    uint32_t head = tb_ttf_table(&f, base, \"head\"), maxp = tb_ttf_table(&f, base, \"maxp\"), hhea = tb_ttf_table(&f, base, \"hhea\");\n"; *(const char * *)tb_grow(v_lines) = tb_v4168; }
    { const char * tb_v4169 = "    f.glyf = tb_ttf_table(&f, base, \"glyf\"); f.loca = tb_ttf_table(&f, base, \"loca\");\n"; *(const char * *)tb_grow(v_lines) = tb_v4169; }
    { const char * tb_v4170 = "    f.hmtx = tb_ttf_table(&f, base, \"hmtx\");\n"; *(const char * *)tb_grow(v_lines) = tb_v4170; }
    { const char * tb_v4171 = "    uint32_t cmap = tb_ttf_table(&f, base, \"cmap\");\n"; *(const char * *)tb_grow(v_lines) = tb_v4171; }
    { const char * tb_v4172 = "    if (!f.glyf || !f.loca) { free(d); tb_err = \"этот шрифт не TrueType (контуры CFF/OTF пока не читаю): возьми .ttf\"; return -1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4172; }
    { const char * tb_v4173 = "    if (!head || !maxp || !hhea || !f.hmtx || !cmap) { free(d); tb_err = \"шрифт сломан: нет нужных таблиц\"; return -1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4173; }
    { const char * tb_v4174 = "    f.upem = (int)tb_u16(&f, head + 18); f.locfmt = tb_s16(&f, head + 50);\n"; *(const char * *)tb_grow(v_lines) = tb_v4174; }
    { const char * tb_v4175 = "    f.nglyphs = (int)tb_u16(&f, maxp + 4);\n"; *(const char * *)tb_grow(v_lines) = tb_v4175; }
    { const char * tb_v4176 = "    f.asc = tb_s16(&f, hhea + 4); f.desc = tb_s16(&f, hhea + 6); f.nhm = (int)tb_u16(&f, hhea + 34);\n"; *(const char * *)tb_grow(v_lines) = tb_v4176; }
    { const char * tb_v4177 = "    if (f.upem <= 0 || f.nhm <= 0 || f.asc - f.desc <= 0) { free(d); tb_err = \"шрифт сломан: размеры\"; return -1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4177; }
    { const char * tb_v4178 = "    // буквы → номера глифов: Unicode-таблица формата 12 (все буквы) или 4 (до U+FFFF)\n"; *(const char * *)tb_grow(v_lines) = tb_v4178; }
    { const char * tb_v4179 = "    unsigned nt = tb_u16(&f, cmap + 2);\n"; *(const char * *)tb_grow(v_lines) = tb_v4179; }
    { const char * tb_v4180 = "    int best = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4180; }
    { const char * tb_v4181 = "    for (unsigned i = 0; i < nt; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4181; }
    { const char * tb_v4182 = "        size_t e = cmap + 4 + 8 * (size_t)i;\n"; *(const char * *)tb_grow(v_lines) = tb_v4182; }
    { const char * tb_v4183 = "        unsigned pid = tb_u16(&f, e), eid = tb_u16(&f, e + 2);\n"; *(const char * *)tb_grow(v_lines) = tb_v4183; }
    { const char * tb_v4184 = "        uint32_t off = cmap + tb_u32(&f, e + 4);\n"; *(const char * *)tb_grow(v_lines) = tb_v4184; }
    { const char * tb_v4185 = "        unsigned fmt = tb_u16(&f, off);\n"; *(const char * *)tb_grow(v_lines) = tb_v4185; }
    { const char * tb_v4186 = "        int score = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4186; }
    { const char * tb_v4187 = "        if (fmt == 12 && (pid == 0 || (pid == 3 && eid == 10))) score = 3;\n"; *(const char * *)tb_grow(v_lines) = tb_v4187; }
    { const char * tb_v4188 = "        else if (fmt == 4 && (pid == 0 || (pid == 3 && eid == 1))) score = 2;\n"; *(const char * *)tb_grow(v_lines) = tb_v4188; }
    { const char * tb_v4189 = "        if (score > best) { best = score; f.cmap = off; f.cfmt = (int)fmt; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4189; }
    { const char * tb_v4190 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v4190; }
    { const char * tb_v4191 = "    if (!best) { free(d); tb_err = \"в шрифте нет таблицы букв Unicode\"; return -1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4191; }
    { const char * tb_v4192 = "    tb_font_t *all = realloc(tb_fonts, (size_t)(tb_nfonts + 1) * sizeof(tb_font_t));\n"; *(const char * *)tb_grow(v_lines) = tb_v4192; }
    { const char * tb_v4193 = "    if (!all) { free(d); tb_err = \"не хватило памяти\"; return -1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4193; }
    { const char * tb_v4194 = "    tb_fonts = all;\n"; *(const char * *)tb_grow(v_lines) = tb_v4194; }
    { const char * tb_v4195 = "    tb_fonts[tb_nfonts++] = f;\n"; *(const char * *)tb_grow(v_lines) = tb_v4195; }
    { const char * tb_v4196 = "    tb_gpu_blend_probe();\n"; *(const char * *)tb_grow(v_lines) = tb_v4196; }
    { const char * tb_v4197 = "    return tb_nfonts - 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v4197; }
    { const char * tb_v4198 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v4198; }
    { const char * tb_v4199 = "static unsigned tb_ttf_glyph(const tb_font_t *f, unsigned u) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4199; }
    { const char * tb_v4200 = "    size_t c = f->cmap;\n"; *(const char * *)tb_grow(v_lines) = tb_v4200; }
    { const char * tb_v4201 = "    if (f->cfmt == 12) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4201; }
    { const char * tb_v4202 = "        uint32_t n = tb_u32(f, c + 12);\n"; *(const char * *)tb_grow(v_lines) = tb_v4202; }
    { const char * tb_v4203 = "        for (uint32_t lo = 0, hi = n; lo < hi;) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4203; }
    { const char * tb_v4204 = "            uint32_t mid = (lo + hi) / 2; size_t g = c + 16 + 12 * (size_t)mid;\n"; *(const char * *)tb_grow(v_lines) = tb_v4204; }
    { const char * tb_v4205 = "            uint32_t a = tb_u32(f, g), b = tb_u32(f, g + 4);\n"; *(const char * *)tb_grow(v_lines) = tb_v4205; }
    { const char * tb_v4206 = "            if (u < a) hi = mid; else if (u > b) lo = mid + 1; else return tb_u32(f, g + 8) + (u - a);\n"; *(const char * *)tb_grow(v_lines) = tb_v4206; }
    { const char * tb_v4207 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v4207; }
    { const char * tb_v4208 = "        return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4208; }
