    { const char * tb_v4492 = "        if (gc->img >= 0) tb_draw_image_a(gc->img, gx + gc->left, base + gc->top);\n"; *(const char * *)tb_grow(v_lines) = tb_v4492; }
    { const char * tb_v4493 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v4493; }
    { const char * tb_v4494 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v4494; }
    { const char * tb_v4495 = "// ---------- рисование на видеокарте (GPU) ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v4495; }
    { const char * tb_v4496 = "// Кадр не рисуется точками на процессоре: каждая фигура записывается как «экземпляр»\n"; *(const char * *)tb_grow(v_lines) = tb_v4496; }
    { const char * tb_v4497 = "// (прямоугольник, круг или буква), а видеокарта рисует их все разом — по тем же правилам\n"; *(const char * *)tb_grow(v_lines) = tb_v4497; }
    { const char * tb_v4498 = "// точек, что и процессор (tb_draw_* ниже). Mac — Metal, Linux и Windows — Vulkan.\n"; *(const char * *)tb_grow(v_lines) = tb_v4498; }
    { const char * tb_v4499 = "// Если видеокарты нет (нет драйвера Vulkan, нет экрана) — рисуем как раньше, на процессоре.\n"; *(const char * *)tb_grow(v_lines) = tb_v4499; }
    { const char * tb_v4500 = "//   TB_GPU=0        — всегда на процессоре\n"; *(const char * *)tb_grow(v_lines) = tb_v4500; }
    { const char * tb_v4501 = "//   TB_GPU_CHECK=1  — рисовать и там и там и сверять каждый кадр точка в точку\n"; *(const char * *)tb_grow(v_lines) = tb_v4501; }
    { const char * tb_v4502 = "//   TB_GPU_INFO=1   — сказать, чем рисуем\n"; *(const char * *)tb_grow(v_lines) = tb_v4502; }
    { const char * tb_v4503 = "typedef struct { int32_t x0, y0, x1, y1, ox, oy; uint32_t c, m; } tb_ginst;   // 32 байта\n"; *(const char * *)tb_grow(v_lines) = tb_v4503; }
    { const char * tb_v4504 = "enum { TB_GI_CAP = 65536 };\n"; *(const char * *)tb_grow(v_lines) = tb_v4504; }
    { const char * tb_v4505 = "TB_API int tb_gpu_on = 0, tb_gpu_check = 0, tb_gpu_first = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v4505; }
    { const char * tb_v4506 = "TB_API tb_ginst *tb_gi = 0;            // память экземпляров (видна видеокарте)\n"; *(const char * *)tb_grow(v_lines) = tb_v4506; }
    { const char * tb_v4507 = "TB_API int tb_gin = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4507; }
    { const char * tb_v4508 = "// 3D: глубина. У треугольника сетки своя «плоскость глубины» A, B, C (целые числа, см. tb_tri3_depth);\n"; *(const char * *)tb_grow(v_lines) = tb_v4508; }
    { const char * tb_v4509 = "// она лежит в tb_gplane[набор * TB_GI_CAP + номер фигуры], а в m — 2 | (это место << 2)\n"; *(const char * *)tb_grow(v_lines) = tb_v4509; }
    { const char * tb_v4510 = "typedef struct { uint32_t a, b, c, pad; } tb_gplane_t;\n"; *(const char * *)tb_grow(v_lines) = tb_v4510; }
    { const char * tb_v4511 = "TB_API tb_gplane_t *tb_gplane = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4511; }
    { const char * tb_v4512 = "TB_API int tb_gzclr = 1;               // видеокарта: в начале кадра стереть глубину\n"; *(const char * *)tb_grow(v_lines) = tb_v4512; }
    { const char * tb_v4513 = "TB_API int tb_zclr = 1;                // процессор: то же для tb_zb\n"; *(const char * *)tb_grow(v_lines) = tb_v4513; }
    { const char * tb_v4514 = "TB_API uint32_t *tb_zb = 0;            // процессор: глубина каждой точки\n"; *(const char * *)tb_grow(v_lines) = tb_v4514; }
    { const char * tb_v4515 = "TB_API long long tb_zb_n = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4515; }
    { const char * tb_v4516 = "// 3D на видеокарте: сетка один раз ложится в память видеокарты (tb_mesh_pack), а на каждый draw_mesh\n"; *(const char * *)tb_grow(v_lines) = tb_v4516; }
    { const char * tb_v4517 = "// пишется только запись: 3 строки по 4 целых — поворот (камера × поворот сетки) × 2^30 и сдвиг × 4096.\n"; *(const char * *)tb_grow(v_lines) = tb_v4517; }
    { const char * tb_v4518 = "// В пачке фигур это одна особая фигура m = 3: x0 — сетка, y0 — какие грани не видны, x1 — первая запись,\n"; *(const char * *)tb_grow(v_lines) = tb_v4518; }
    { const char * tb_v4519 = "// y1 — сколько записей подряд. Углы, экран и глубину считает видеокарта (tb3.vert) целыми числами —\n"; *(const char * *)tb_grow(v_lines) = tb_v4519; }
    { const char * tb_v4520 = "// той же формулой, что процессор (tb_m3_corner): кадры совпадают точка в точку\n"; *(const char * *)tb_grow(v_lines) = tb_v4520; }
    { const char * tb_v4521 = "typedef struct { int32_t r[12]; } tb_grec;\n"; *(const char * *)tb_grow(v_lines) = tb_v4521; }
    { const char * tb_v4522 = "enum { TB_GR_CAP = 65536 };\n"; *(const char * *)tb_grow(v_lines) = tb_v4522; }
    { const char * tb_v4523 = "TB_API tb_grec *tb_grec_p = 0;         // записи всех наборов подряд (видны видеокарте)\n"; *(const char * *)tb_grow(v_lines) = tb_v4523; }
    { const char * tb_v4524 = "TB_API int tb_grn = 0;                 // сколько записей в текущем наборе\n"; *(const char * *)tb_grow(v_lines) = tb_v4524; }
    { const char * tb_v4525 = "TB_API int tb_gpu_mesh = 0;            // 1: видеокарта умеет считать сетки сама (конвейер собрался)\n"; *(const char * *)tb_grow(v_lines) = tb_v4525; }
    { const char * tb_v4526 = "TB_API int tb_mesh_gdirty = 1;         // сетки поменялись: перед рисованием залить заново\n"; *(const char * *)tb_grow(v_lines) = tb_v4526; }
    { const char * tb_v4527 = "TB_API long long tb_gbatch = 1;        // номер текущей пачки (растёт после каждой отдачи видеокарте)\n"; *(const char * *)tb_grow(v_lines) = tb_v4527; }
    { const char * tb_v4528 = "typedef struct { float size[2]; int32_t tbase, ntri, rbase, f, gw, gh, cull; } tb_gpc;   // постоянные шейдера сеток\n"; *(const char * *)tb_grow(v_lines) = tb_v4528; }
    { const char * tb_v4529 = "TB_API long long tb_mesh_pack(int32_t *dst);   // все сетки подряд для видеокарты (dst = 0: только размер)\n"; *(const char * *)tb_grow(v_lines) = tb_v4529; }
    { const char * tb_v4530 = "TB_API void tb_mesh_gpc(const tb_ginst *g, int slot, tb_gpc *pc);   // постоянные для фигуры m = 3\n"; *(const char * *)tb_grow(v_lines) = tb_v4530; }
    { const char * tb_v4531 = "// TB_GSLOTS наборов памяти по кругу: пока видеокарта рисует один кадр, программа уже пишет следующий\n"; *(const char * *)tb_grow(v_lines) = tb_v4531; }
    { const char * tb_v4532 = "enum { TB_GSLOTS = 3 };\n"; *(const char * *)tb_grow(v_lines) = tb_v4532; }
    { const char * tb_v4533 = "TB_API int tb_gslot = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4533; }
    { const char * tb_v4534 = "TB_API uint32_t *tb_gpu_back = 0;      // TB_GPU_CHECK: кадр, прочитанный обратно с видеокарты\n"; *(const char * *)tb_grow(v_lines) = tb_v4534; }
    { const char * tb_v4535 = "TB_API long long tb_gpu_frames = 0, tb_gpu_bad = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4535; }
    { const char * tb_v4536 = "TB_API void tb_gpu_flush(int present);   // своя у каждой системы: Metal или Vulkan\n"; *(const char * *)tb_grow(v_lines) = tb_v4536; }
    { const char * tb_v4537 = "TB_API void tb_gpu_vsync(void);          // включить или выключить ожидание экрана (tb_gpu_nosync)\n"; *(const char * *)tb_grow(v_lines) = tb_v4537; }
    { const char * tb_v4538 = "TB_API int tb_gpu_nosync = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4538; }
    { const char * tb_v4539 = "TB_API int tb_gpu_resize(int ow, int oh);   // окно поменяло размер\n"; *(const char * *)tb_grow(v_lines) = tb_v4539; }
    { const char * tb_v4540 = "// окно можно тянуть мышью, если программа спросила его размер (window_w, window_h)\n"; *(const char * *)tb_grow(v_lines) = tb_v4540; }
    { const char * tb_v4541 = "TB_API int tb_resizable = 0, tb_new_w = 0, tb_new_h = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4541; }
    { const char * tb_v4542 = "TB_API int tb_sharp = 0;       // window_sharp(): окно в настоящих точках экрана\n"; *(const char * *)tb_grow(v_lines) = tb_v4542; }
    { const char * tb_v4543 = "TB_API double tb_sc = 1;        // во сколько раз точек больше (Retina — 2)\n"; *(const char * *)tb_grow(v_lines) = tb_v4543; }
    { const char * tb_v4544 = "TB_API void tb_gfx_resizable(void);   // свои у каждой системы\n"; *(const char * *)tb_grow(v_lines) = tb_v4544; }
    { const char * tb_v4545 = "TB_API void tb_gfx_reimage(void);            // 1: не ждать обновления экрана (set_fps(0), TB_FPS_FREE=1)\n"; *(const char * *)tb_grow(v_lines) = tb_v4545; }
    { const char * tb_v4546 = "TB_API int tb_gpu_want(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4546; }
    { const char * tb_v4547 = "    const char *e = getenv(\"TB_GPU\");\n"; *(const char * *)tb_grow(v_lines) = tb_v4547; }
    { const char * tb_v4548 = "    tb_gpu_check = getenv(\"TB_GPU_CHECK\") != 0 && getenv(\"TB_GPU_CHECK\")[0] == '1';\n"; *(const char * *)tb_grow(v_lines) = tb_v4548; }
    { const char * tb_v4549 = "    if (getenv(\"TB_FPS_FREE\")) tb_gpu_nosync = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v4549; }
    { const char * tb_v4550 = "    return !(e && e[0] == '0');\n"; *(const char * *)tb_grow(v_lines) = tb_v4550; }
    { const char * tb_v4551 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v4551; }
    { const char * tb_v4552 = "TB_API void tb_gpu_say(const char *what) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4552; }
    { const char * tb_v4553 = "    const char *e = getenv(\"TB_GPU_INFO\");\n"; *(const char * *)tb_grow(v_lines) = tb_v4553; }
    { const char * tb_v4554 = "    if ((e && e[0] == '1') || tb_gpu_check) fprintf(stderr, \"окно: рисует %s\\n\", what);\n"; *(const char * *)tb_grow(v_lines) = tb_v4554; }
    { const char * tb_v4555 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v4555; }
    { const char * tb_v4556 = "TB_API void tb_gpu_report(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4556; }
    { const char * tb_v4557 = "    fprintf(stderr, \"TB_GPU_CHECK: кадров %lld, разошлось %lld\\n\", tb_gpu_frames, tb_gpu_bad);\n"; *(const char * *)tb_grow(v_lines) = tb_v4557; }
    { const char * tb_v4558 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v4558; }
    { const char * tb_v4559 = "// сверить кадр видеокарты с кадром процессора (видны только младшие 24 бита цвета)\n"; *(const char * *)tb_grow(v_lines) = tb_v4559; }
    { const char * tb_v4560 = "// TB_GPU_CHECK: как видеокарта смешивает букву с фоном — таблица из пробы (tb_gpu_blend_probe)\n"; *(const char * *)tb_grow(v_lines) = tb_v4560; }
    { const char * tb_v4561 = "TB_API int tb_blend_cal = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4561; }
    { const char * tb_v4562 = "TB_API uint8_t *tb_blend_lut = 0;   // [цвет][фон][a] → точка, 2^24 байт\n"; *(const char * *)tb_grow(v_lines) = tb_v4562; }
    { const char * tb_v4563 = "TB_API int tb_gpu_probing = 0;   // TB_GPU_CHECK: идёт проба смешивания (tb_gpu_blend_probe), кадры не сверять\n"; *(const char * *)tb_grow(v_lines) = tb_v4563; }
    { const char * tb_v4564 = "TB_API void tb_gpu_compare(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4564; }
    { const char * tb_v4565 = "    if (!tb_gpu_back || tb_gpu_probing) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v4565; }
    { const char * tb_v4566 = "    tb_gpu_frames++;\n"; *(const char * *)tb_grow(v_lines) = tb_v4566; }
    { const char * tb_v4567 = "    long long n = (long long)tb_gw * tb_gh, bad = 0, first = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v4567; }
    { const char * tb_v4568 = "    for (long long i = 0; i < n; i++)\n"; *(const char * *)tb_grow(v_lines) = tb_v4568; }
    { const char * tb_v4569 = "        if (((tb_gpu_back[i] ^ tb_px[i]) & 0xFFFFFF) != 0) { if (first < 0) first = i; bad++; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4569; }
    { const char * tb_v4570 = "    if (bad) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4570; }
    { const char * tb_v4571 = "        tb_gpu_bad++;\n"; *(const char * *)tb_grow(v_lines) = tb_v4571; }
    { const char * tb_v4572 = "        if (tb_gpu_bad <= 5)\n"; *(const char * *)tb_grow(v_lines) = tb_v4572; }
    { const char * tb_v4573 = "            fprintf(stderr, \"TB_GPU_CHECK: кадр %lld: не совпало точек %lld, первая x=%lld y=%lld: видеокарта %06x, процессор %06x\\n\",\n"; *(const char * *)tb_grow(v_lines) = tb_v4573; }
    { const char * tb_v4574 = "                tb_gpu_frames, bad, first % tb_gw, first / tb_gw, tb_gpu_back[first] & 0xFFFFFF, tb_px[first] & 0xFFFFFF);\n"; *(const char * *)tb_grow(v_lines) = tb_v4574; }
    { const char * tb_v4575 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v4575; }
    { const char * tb_v4576 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v4576; }
    { const char * tb_v4577 = "TB_INL void tb_gpu_add(long long x0, long long y0, long long x1, long long y1, long long ox, long long oy, uint32_t c, uint32_t m) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4577; }
    { const char * tb_v4578 = "    if (tb_gin == TB_GI_CAP) tb_gpu_flush(0);\n"; *(const char * *)tb_grow(v_lines) = tb_v4578; }
    { const char * tb_v4579 = "    tb_ginst *g = &tb_gi[tb_gin++];\n"; *(const char * *)tb_grow(v_lines) = tb_v4579; }
    { const char * tb_v4580 = "    g->x0 = (int32_t)x0; g->y0 = (int32_t)y0; g->x1 = (int32_t)x1; g->y1 = (int32_t)y1;\n"; *(const char * *)tb_grow(v_lines) = tb_v4580; }
    { const char * tb_v4581 = "    g->ox = (int32_t)ox; g->oy = (int32_t)oy; g->c = c; g->m = m;\n"; *(const char * *)tb_grow(v_lines) = tb_v4581; }
    { const char * tb_v4582 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v4582; }
    { const char * tb_v4583 = "// прямоугольник: обрезан окном; соседние полоски одного цвета склеиваются (линии, точки по одной)\n"; *(const char * *)tb_grow(v_lines) = tb_v4583; }
    { const char * tb_v4584 = "TB_API void tb_gpu_rect(long long x, long long y, long long w, long long h, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4584; }
    { const char * tb_v4585 = "    long long x0 = x < 0 ? 0 : x, y0 = y < 0 ? 0 : y, x1 = x + w > tb_gw ? tb_gw : x + w, y1 = y + h > tb_gh ? tb_gh : y + h;\n"; *(const char * *)tb_grow(v_lines) = tb_v4585; }
    { const char * tb_v4586 = "    if (x0 >= x1 || y0 >= y1) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v4586; }
    { const char * tb_v4587 = "    uint32_t cc = (uint32_t)c & 0xFFFFFF;\n"; *(const char * *)tb_grow(v_lines) = tb_v4587; }
    { const char * tb_v4588 = "    if (tb_gin > 0) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4588; }
    { const char * tb_v4589 = "        tb_ginst *g = &tb_gi[tb_gin - 1];\n"; *(const char * *)tb_grow(v_lines) = tb_v4589; }
    { const char * tb_v4590 = "        if (g->m == 0 && g->c == cc) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4590; }
    { const char * tb_v4591 = "            if (g->y0 == y0 && g->y1 == y1) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4591; }
    { const char * tb_v4592 = "                if (g->x1 == x0) { g->x1 = (int32_t)x1; return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4592; }
    { const char * tb_v4593 = "                if (g->x0 == x1) { g->x0 = (int32_t)x0; return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4593; }
    { const char * tb_v4594 = "            }\n"; *(const char * *)tb_grow(v_lines) = tb_v4594; }
    { const char * tb_v4595 = "            if (g->x0 == x0 && g->x1 == x1) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4595; }
    { const char * tb_v4596 = "                if (g->y1 == y0) { g->y1 = (int32_t)y1; return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4596; }
    { const char * tb_v4597 = "                if (g->y0 == y1) { g->y0 = (int32_t)y0; return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4597; }
    { const char * tb_v4598 = "            }\n"; *(const char * *)tb_grow(v_lines) = tb_v4598; }
    { const char * tb_v4599 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v4599; }
    { const char * tb_v4600 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v4600; }
    { const char * tb_v4601 = "    tb_gpu_add(x0, y0, x1, y1, 0, 0, cc, 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v4601; }
    { const char * tb_v4602 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v4602; }
    { const char * tb_v4603 = "TB_API void tb_gpu_circle(long long cx, long long cy, long long r, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4603; }
    { const char * tb_v4604 = "    if (r < 0 || cx + r < 0 || cy + r < 0 || cx - r >= tb_gw || cy - r >= tb_gh) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v4604; }
    { const char * tb_v4605 = "    if (r <= 16384) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4605; }
    { const char * tb_v4606 = "        long long x0 = cx - r < 0 ? 0 : cx - r, y0 = cy - r < 0 ? 0 : cy - r;\n"; *(const char * *)tb_grow(v_lines) = tb_v4606; }
    { const char * tb_v4607 = "        long long x1 = cx + r + 1 > tb_gw ? tb_gw : cx + r + 1, y1 = cy + r + 1 > tb_gh ? tb_gh : cy + r + 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v4607; }
    { const char * tb_v4608 = "        tb_gpu_add(x0, y0, x1, y1, cx, cy, (uint32_t)c & 0xFFFFFF, (1u << 30) | (uint32_t)r);\n"; *(const char * *)tb_grow(v_lines) = tb_v4608; }
    { const char * tb_v4609 = "        return;\n"; *(const char * *)tb_grow(v_lines) = tb_v4609; }
    { const char * tb_v4610 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v4610; }
    { const char * tb_v4611 = "    // огромный круг: по строкам, полосками (то же правило i*i + j*j <= r*r + r)\n"; *(const char * *)tb_grow(v_lines) = tb_v4611; }
    { const char * tb_v4612 = "    long long ja = -r > -cy ? -r : -cy, jb = r < tb_gh - 1 - cy ? r : tb_gh - 1 - cy;\n"; *(const char * *)tb_grow(v_lines) = tb_v4612; }
    { const char * tb_v4613 = "    for (long long j = ja; j <= jb; j++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4613; }
    { const char * tb_v4614 = "        long long rest = r * r + r - j * j, i = (long long)sqrt((double)rest);\n"; *(const char * *)tb_grow(v_lines) = tb_v4614; }
    { const char * tb_v4615 = "        while (i * i > rest) i--;\n"; *(const char * *)tb_grow(v_lines) = tb_v4615; }
    { const char * tb_v4616 = "        while ((i + 1) * (i + 1) <= rest) i++;\n"; *(const char * *)tb_grow(v_lines) = tb_v4616; }
    { const char * tb_v4617 = "        tb_gpu_rect(cx - i, cy + j, 2 * i + 1, 1, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v4617; }
    { const char * tb_v4618 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v4618; }
    { const char * tb_v4619 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v4619; }
    { const char * tb_v4620 = "TB_API void tb_gpu_image(long long id, long long x, long long y) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4620; }
    { const char * tb_v4621 = "    tb_image *im = &tb_imgs[id];\n"; *(const char * *)tb_grow(v_lines) = tb_v4621; }
    { const char * tb_v4622 = "    if (x >= tb_gw || y >= tb_gh || x + im->w <= 0 || y + im->h <= 0) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v4622; }
    { const char * tb_v4623 = "    long long x0 = x < 0 ? 0 : x, y0 = y < 0 ? 0 : y;\n"; *(const char * *)tb_grow(v_lines) = tb_v4623; }
    { const char * tb_v4624 = "    long long x1 = x + im->w > tb_gw ? tb_gw : x + im->w, y1 = y + im->h > tb_gh ? tb_gh : y + im->h;\n"; *(const char * *)tb_grow(v_lines) = tb_v4624; }
    { const char * tb_v4625 = "    tb_gpu_add(x0, y0, x1, y1, x, y, im->off, (3u << 30) | (uint32_t)im->w);\n"; *(const char * *)tb_grow(v_lines) = tb_v4625; }
    { const char * tb_v4626 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v4626; }
    { const char * tb_v4627 = "// картинка с настоящей прозрачностью (буквы шрифта): видеокарта смешивает с тем, что уже нарисовано\n"; *(const char * *)tb_grow(v_lines) = tb_v4627; }
    { const char * tb_v4628 = "TB_API void tb_gpu_image_a(long long id, long long x, long long y) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4628; }
    { const char * tb_v4629 = "    tb_image *im = &tb_imgs[id];\n"; *(const char * *)tb_grow(v_lines) = tb_v4629; }
    { const char * tb_v4630 = "    if (x >= tb_gw || y >= tb_gh || x + im->w <= 0 || y + im->h <= 0) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v4630; }
    { const char * tb_v4631 = "    long long x0 = x < 0 ? 0 : x, y0 = y < 0 ? 0 : y;\n"; *(const char * *)tb_grow(v_lines) = tb_v4631; }
    { const char * tb_v4632 = "    long long x1 = x + im->w > tb_gw ? tb_gw : x + im->w, y1 = y + im->h > tb_gh ? tb_gh : y + im->h;\n"; *(const char * *)tb_grow(v_lines) = tb_v4632; }
    { const char * tb_v4633 = "    tb_gpu_add(x0, y0, x1, y1, x, y, im->off, (3u << 30) | (1u << 29) | (uint32_t)im->w);\n"; *(const char * *)tb_grow(v_lines) = tb_v4633; }
    { const char * tb_v4634 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v4634; }
