    { const char * tb_v4646 = "    tb_gpu_add(t[0], t[1], t[2], t[3], t[4], t[5], (uint32_t)c & 0xFFFFFF, 2u | (at << 2));\n"; *(const char * *)tb_grow(v_lines) = tb_v4646; }
    { const char * tb_v4647 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v4647; }
    { const char * tb_v4648 = "TB_API void tb_gpu_glyph(long long x, long long y, int g, long long size, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4648; }
    { const char * tb_v4649 = "    if (x >= tb_gw || y >= tb_gh || x + 8 * size <= 0 || y + 16 * size <= 0) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v4649; }
    { const char * tb_v4650 = "    if (size >= (1 << 22) || x < -(1LL << 30) || y < -(1LL << 30)) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4650; }
    { const char * tb_v4651 = "        for (int row = 0; row < 16; row++) for (int col = 0; col < 8; col++)\n"; *(const char * *)tb_grow(v_lines) = tb_v4651; }
    { const char * tb_v4652 = "            if (tb_font[g][row] & (0x80 >> col)) tb_gpu_rect(x + col * size, y + row * size, size, size, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v4652; }
    { const char * tb_v4653 = "        return;\n"; *(const char * *)tb_grow(v_lines) = tb_v4653; }
