    { const char * tb_v6940 = "    struct { uint32_t sType; const void *pNext; VkFlags flags; Display *dpy; Window window; } ci = { 1000004000, 0, 0, tb_dpy, tb_xw };\n"; *(const char * *)tb_grow(v_lines) = tb_v6940; }
    { const char * tb_v6941 = "    VkResult (TBVK_CALL *mk)(VkInstance, const void *, const void *, VkSurfaceKHR *) =\n"; *(const char * *)tb_grow(v_lines) = tb_v6941; }
    { const char * tb_v6942 = "        (VkResult (TBVK_CALL *)(VkInstance, const void *, const void *, VkSurfaceKHR *))tbvk_gipa(tb_vk.inst, \"vkCreateXlibSurfaceKHR\");\n"; *(const char * *)tb_grow(v_lines) = tb_v6942; }
    { const char * tb_v6943 = "    return mk && mk(tb_vk.inst, &ci, 0, &tb_vk.surf) == 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6943; }
