    { const char * tb_v6945 = "// window_sharp в X11: масштаб из настройки Xft.dpi (её ставят GNOME и KDE), иначе 1\n"; *(const char * *)tb_grow(v_lines) = tb_v6945; }
    { const char * tb_v6946 = "TB_API double tb_gfx_scale(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6946; }
    { const char * tb_v6947 = "    if (!tb_dpy) tb_dpy = XOpenDisplay(0);\n"; *(const char * *)tb_grow(v_lines) = tb_v6947; }
    { const char * tb_v6948 = "    if (!tb_dpy) return 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v6948; }
    { const char * tb_v6949 = "    const char *v = XGetDefault(tb_dpy, \"Xft\", \"dpi\");\n"; *(const char * *)tb_grow(v_lines) = tb_v6949; }
