    { const char * tb_v6951 = "    return dpi > 0 ? dpi / 96.0 : 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v6951; }
    { const char * tb_v6952 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6952; }
    { const char * tb_v6953 = "TB_API int tb_gfx_open(const char *title) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6953; }
    { const char * tb_v6954 = "    if (!tb_dpy) tb_dpy = XOpenDisplay(0);\n"; *(const char * *)tb_grow(v_lines) = tb_v6954; }
    { const char * tb_v6955 = "    if (!tb_dpy) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6955; }
    { const char * tb_v6956 = "    int scr = DefaultScreen(tb_dpy);\n"; *(const char * *)tb_grow(v_lines) = tb_v6956; }
    { const char * tb_v6957 = "    tb_xw = XCreateSimpleWindow(tb_dpy, RootWindow(tb_dpy, scr), 0, 0, tb_gw, tb_gh, 0, 0, 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v6957; }
    { const char * tb_v6958 = "    tb_xgc = XCreateGC(tb_dpy, tb_xw, 0, 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v6958; }
    { const char * tb_v6959 = "    XSelectInput(tb_dpy, tb_xw, ExposureMask | KeyPressMask | KeyReleaseMask | ButtonPressMask | ButtonReleaseMask | PointerMotionMask | StructureNotifyMask);\n"; *(const char * *)tb_grow(v_lines) = tb_v6959; }
    { const char * tb_v6960 = "    tb_x_hints(tb_gw, tb_gh, tb_gw, tb_gh);   // размер окна не меняется, пока программа не спросит window_w()\n"; *(const char * *)tb_grow(v_lines) = tb_v6960; }
    { const char * tb_v6961 = "    Xutf8SetWMProperties(tb_dpy, tb_xw, title, title, 0, 0, 0, 0, 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v6961; }
    { const char * tb_v6962 = "    tb_wm_del = XInternAtom(tb_dpy, \"WM_DELETE_WINDOW\", False);\n"; *(const char * *)tb_grow(v_lines) = tb_v6962; }
    { const char * tb_v6963 = "    XSetWMProtocols(tb_dpy, tb_xw, &tb_wm_del, 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v6963; }
    { const char * tb_v6964 = "    XkbSetDetectableAutoRepeat(tb_dpy, True, 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v6964; }
    { const char * tb_v6965 = "    XMapWindow(tb_dpy, tb_xw);\n"; *(const char * *)tb_grow(v_lines) = tb_v6965; }
    { const char * tb_v6966 = "    tb_ximg = XCreateImage(tb_dpy, DefaultVisual(tb_dpy, scr), 24, ZPixmap, 0, (char *)tb_px, tb_gw, tb_gh, 32, 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v6966; }
    { const char * tb_v6967 = "    if (tb_gpu_want()) tb_gpu_on = tb_vk_init(\"VK_KHR_xlib_surface\", tb_x_surface);\n"; *(const char * *)tb_grow(v_lines) = tb_v6967; }
    { const char * tb_v6968 = "    if (!tb_gpu_on) tb_gpu_say(\"процессор\");\n"; *(const char * *)tb_grow(v_lines) = tb_v6968; }
    { const char * tb_v6969 = "    if (tb_cursor_want) tb_gfx_cursor(tb_cursor_want);\n"; *(const char * *)tb_grow(v_lines) = tb_v6969; }
    { const char * tb_v6970 = "    return 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v6970; }
    { const char * tb_v6971 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6971; }
    { const char * tb_v6972 = "// знак клавиши → буква Unicode (русская раскладка в X11 — свои старые номера 0x6c0..0x6ff)\n"; *(const char * *)tb_grow(v_lines) = tb_v6972; }
    { const char * tb_v6973 = "TB_API unsigned tb_x_uni(KeySym s) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6973; }
    { const char * tb_v6974 = "    static const unsigned short cyr[64] = { 0x44e, 0x430, 0x431, 0x446, 0x434, 0x435, 0x444, 0x433, 0x445, 0x438, 0x439, 0x43a, 0x43b, 0x43c, 0x43d, 0x43e, 0x43f, 0x44f, 0x440, 0x441, 0x442, 0x443, 0x436, 0x432, 0x44c, 0x44b, 0x437, 0x448, 0x44d, 0x449, 0x447, 0x44a, 0x42e, 0x410, 0x411, 0x426, 0x414, 0x415, 0x424, 0x413, 0x425, 0x418, 0x419, 0x41a, 0x41b, 0x41c, 0x41d, 0x41e, 0x41f, 0x42f, 0x420, 0x421, 0x422, 0x423, 0x416, 0x412, 0x42c, 0x42b, 0x417, 0x428, 0x42d, 0x429, 0x427, 0x42a };\n"; *(const char * *)tb_grow(v_lines) = tb_v6974; }
    { const char * tb_v6975 = "    if ((s >= 0x20 && s <= 0x7e) || (s >= 0xa0 && s <= 0xff)) return (unsigned)s;\n"; *(const char * *)tb_grow(v_lines) = tb_v6975; }
    { const char * tb_v6976 = "    if ((s & 0xff000000) == 0x01000000) return (unsigned)(s & 0xffffff);\n"; *(const char * *)tb_grow(v_lines) = tb_v6976; }
    { const char * tb_v6977 = "    if (s >= 0x6c0 && s <= 0x6ff) return cyr[s - 0x6c0];\n"; *(const char * *)tb_grow(v_lines) = tb_v6977; }
    { const char * tb_v6978 = "    if (s == 0x6a3) return 0x451;\n"; *(const char * *)tb_grow(v_lines) = tb_v6978; }
    { const char * tb_v6979 = "    if (s == 0x6b3) return 0x401;\n"; *(const char * *)tb_grow(v_lines) = tb_v6979; }
    { const char * tb_v6980 = "    return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6980; }
    { const char * tb_v6981 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6981; }
    { const char * tb_v6982 = "TB_API int tb_x_key(KeySym s) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6982; }
    { const char * tb_v6983 = "    if (s >= XK_a && s <= XK_z) return 'A' + (int)(s - XK_a);\n"; *(const char * *)tb_grow(v_lines) = tb_v6983; }
    { const char * tb_v6984 = "    if (s >= XK_A && s <= XK_Z) return 'A' + (int)(s - XK_A);\n"; *(const char * *)tb_grow(v_lines) = tb_v6984; }
    { const char * tb_v6985 = "    if (s >= XK_0 && s <= XK_9) return '0' + (int)(s - XK_0);\n"; *(const char * *)tb_grow(v_lines) = tb_v6985; }
    { const char * tb_v6986 = "    switch (s) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6986; }
    { const char * tb_v6987 = "    case XK_Return: return TB_K_ENTER; case XK_Escape: return TB_K_ESC; case XK_space: return TB_K_SPACE;\n"; *(const char * *)tb_grow(v_lines) = tb_v6987; }
    { const char * tb_v6988 = "    case XK_BackSpace: return TB_K_BACK; case XK_Tab: return TB_K_TAB; case XK_Up: return TB_K_UP;\n"; *(const char * *)tb_grow(v_lines) = tb_v6988; }
    { const char * tb_v6989 = "    case XK_Down: return TB_K_DOWN; case XK_Left: return TB_K_LEFT; case XK_Right: return TB_K_RIGHT;\n"; *(const char * *)tb_grow(v_lines) = tb_v6989; }
    { const char * tb_v6990 = "    case XK_Shift_L: case XK_Shift_R: return TB_K_SHIFT;\n"; *(const char * *)tb_grow(v_lines) = tb_v6990; }
    { const char * tb_v6991 = "    case XK_Control_L: case XK_Control_R: return TB_K_CTRL;\n"; *(const char * *)tb_grow(v_lines) = tb_v6991; }
    { const char * tb_v6992 = "    case XK_Alt_L: case XK_Alt_R: return TB_K_ALT;\n"; *(const char * *)tb_grow(v_lines) = tb_v6992; }
    { const char * tb_v6993 = "    case XK_Delete: return TB_K_DEL; case XK_Home: return TB_K_HOME; case XK_End: return TB_K_END;\n"; *(const char * *)tb_grow(v_lines) = tb_v6993; }
    { const char * tb_v6994 = "    case XK_Prior: return TB_K_PGUP; case XK_Next: return TB_K_PGDN;\n"; *(const char * *)tb_grow(v_lines) = tb_v6994; }
    { const char * tb_v6995 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v6995; }
    { const char * tb_v6996 = "    if (s >= XK_F1 && s <= XK_F12) return TB_K_F1 + (int)(s - XK_F1);\n"; *(const char * *)tb_grow(v_lines) = tb_v6996; }
    { const char * tb_v6997 = "    if (s > 0x20 && s < 0x7f) return (int)s;   // знаки [ ] . , / - = : у X11 номер знака — это его код\n"; *(const char * *)tb_grow(v_lines) = tb_v6997; }
    { const char * tb_v6998 = "    return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6998; }
    { const char * tb_v6999 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6999; }
    { const char * tb_v7000 = "// буфер обмена X11: текст держит сама программа-владелец и отдаёт его по просьбе (SelectionRequest)\n"; *(const char * *)tb_grow(v_lines) = tb_v7000; }
    { const char * tb_v7001 = "TB_API char *tb_x_clip = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7001; }
    { const char * tb_v7002 = "TB_API void tb_x_clip_answer(XSelectionRequestEvent *r) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7002; }
    { const char * tb_v7003 = "    Atom utf8 = XInternAtom(tb_dpy, \"UTF8_STRING\", False), targets = XInternAtom(tb_dpy, \"TARGETS\", False);\n"; *(const char * *)tb_grow(v_lines) = tb_v7003; }
    { const char * tb_v7004 = "    XSelectionEvent ev;\n"; *(const char * *)tb_grow(v_lines) = tb_v7004; }
    { const char * tb_v7005 = "    memset(&ev, 0, sizeof ev);\n"; *(const char * *)tb_grow(v_lines) = tb_v7005; }
    { const char * tb_v7006 = "    ev.type = SelectionNotify; ev.display = r->display; ev.requestor = r->requestor;\n"; *(const char * *)tb_grow(v_lines) = tb_v7006; }
    { const char * tb_v7007 = "    ev.selection = r->selection; ev.target = r->target; ev.time = r->time; ev.property = None;\n"; *(const char * *)tb_grow(v_lines) = tb_v7007; }
    { const char * tb_v7008 = "    Atom prop = r->property ? r->property : r->target;\n"; *(const char * *)tb_grow(v_lines) = tb_v7008; }
    { const char * tb_v7009 = "    if (r->target == targets) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7009; }
    { const char * tb_v7010 = "        Atom list[3] = { targets, utf8, XA_STRING };\n"; *(const char * *)tb_grow(v_lines) = tb_v7010; }
    { const char * tb_v7011 = "        XChangeProperty(tb_dpy, r->requestor, prop, XA_ATOM, 32, PropModeReplace, (unsigned char *)list, 3);\n"; *(const char * *)tb_grow(v_lines) = tb_v7011; }
    { const char * tb_v7012 = "        ev.property = prop;\n"; *(const char * *)tb_grow(v_lines) = tb_v7012; }
    { const char * tb_v7013 = "    } else if ((r->target == utf8 || r->target == XA_STRING) && tb_x_clip) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7013; }
    { const char * tb_v7014 = "        XChangeProperty(tb_dpy, r->requestor, prop, r->target, 8, PropModeReplace, (unsigned char *)tb_x_clip, (int)strlen(tb_x_clip));\n"; *(const char * *)tb_grow(v_lines) = tb_v7014; }
    { const char * tb_v7015 = "        ev.property = prop;\n"; *(const char * *)tb_grow(v_lines) = tb_v7015; }
    { const char * tb_v7016 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v7016; }
    { const char * tb_v7017 = "    XSendEvent(tb_dpy, r->requestor, False, 0, (XEvent *)&ev);\n"; *(const char * *)tb_grow(v_lines) = tb_v7017; }
    { const char * tb_v7018 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7018; }
    { const char * tb_v7019 = "TB_API void tb_gfx_clip_set(const char *s) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7019; }
    { const char * tb_v7020 = "    free(tb_x_clip);\n"; *(const char * *)tb_grow(v_lines) = tb_v7020; }
    { const char * tb_v7021 = "    tb_x_clip = strdup(s);\n"; *(const char * *)tb_grow(v_lines) = tb_v7021; }
    { const char * tb_v7022 = "    if (!tb_dpy) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v7022; }
    { const char * tb_v7023 = "    XSetSelectionOwner(tb_dpy, XInternAtom(tb_dpy, \"CLIPBOARD\", False), tb_xw, CurrentTime);\n"; *(const char * *)tb_grow(v_lines) = tb_v7023; }
    { const char * tb_v7024 = "    XFlush(tb_dpy);\n"; *(const char * *)tb_grow(v_lines) = tb_v7024; }
    { const char * tb_v7025 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7025; }
    { const char * tb_v7026 = "TB_API char *tb_gfx_clip_get(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7026; }
    { const char * tb_v7027 = "    if (!tb_dpy) return tb_x_clip ? strdup(tb_x_clip) : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7027; }
    { const char * tb_v7028 = "    Atom clip = XInternAtom(tb_dpy, \"CLIPBOARD\", False), utf8 = XInternAtom(tb_dpy, \"UTF8_STRING\", False);\n"; *(const char * *)tb_grow(v_lines) = tb_v7028; }
    { const char * tb_v7029 = "    Window owner = XGetSelectionOwner(tb_dpy, clip);\n"; *(const char * *)tb_grow(v_lines) = tb_v7029; }
    { const char * tb_v7030 = "    if (owner == tb_xw) return tb_x_clip ? strdup(tb_x_clip) : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7030; }
    { const char * tb_v7031 = "    if (owner == None) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7031; }
    { const char * tb_v7032 = "    Atom prop = XInternAtom(tb_dpy, \"TACHBIT_CLIP\", False);\n"; *(const char * *)tb_grow(v_lines) = tb_v7032; }
    { const char * tb_v7033 = "    XConvertSelection(tb_dpy, clip, utf8, prop, tb_xw, CurrentTime);\n"; *(const char * *)tb_grow(v_lines) = tb_v7033; }
    { const char * tb_v7034 = "    XFlush(tb_dpy);\n"; *(const char * *)tb_grow(v_lines) = tb_v7034; }
    { const char * tb_v7035 = "    // ждём ответ владельца не дольше полсекунды; чужие события по дороге не теряем\n"; *(const char * *)tb_grow(v_lines) = tb_v7035; }
    { const char * tb_v7036 = "    long long until = tb_time_ms() + 500;\n"; *(const char * *)tb_grow(v_lines) = tb_v7036; }
    { const char * tb_v7037 = "    while (tb_time_ms() < until) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7037; }
    { const char * tb_v7038 = "        XEvent e;\n"; *(const char * *)tb_grow(v_lines) = tb_v7038; }
    { const char * tb_v7039 = "        if (XCheckTypedWindowEvent(tb_dpy, tb_xw, SelectionNotify, &e)) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7039; }
    { const char * tb_v7040 = "            if (e.xselection.property == None) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7040; }
    { const char * tb_v7041 = "            Atom type; int fmt; unsigned long n = 0, rest = 0; unsigned char *data = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7041; }
    { const char * tb_v7042 = "            XGetWindowProperty(tb_dpy, tb_xw, prop, 0, 1 << 24, True, AnyPropertyType, &type, &fmt, &n, &rest, &data);\n"; *(const char * *)tb_grow(v_lines) = tb_v7042; }
    { const char * tb_v7043 = "            char *out = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7043; }
    { const char * tb_v7044 = "            if (data && fmt == 8) { out = malloc(n + 1); if (out) { memcpy(out, data, n); out[n] = 0; } }\n"; *(const char * *)tb_grow(v_lines) = tb_v7044; }
    { const char * tb_v7045 = "            if (data) XFree(data);\n"; *(const char * *)tb_grow(v_lines) = tb_v7045; }
    { const char * tb_v7046 = "            return out;\n"; *(const char * *)tb_grow(v_lines) = tb_v7046; }
    { const char * tb_v7047 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v7047; }
    { const char * tb_v7048 = "        if (XCheckTypedEvent(tb_dpy, SelectionRequest, &e)) tb_x_clip_answer(&e.xselectionrequest);\n"; *(const char * *)tb_grow(v_lines) = tb_v7048; }
    { const char * tb_v7049 = "        struct timespec ts = { 0, 2000000 };\n"; *(const char * *)tb_grow(v_lines) = tb_v7049; }
    { const char * tb_v7050 = "        nanosleep(&ts, 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v7050; }
    { const char * tb_v7051 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v7051; }
    { const char * tb_v7052 = "    return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7052; }
    { const char * tb_v7053 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7053; }
