    { const char * tb_v7085 = "            if (e.xbutton.button == 1) { tb_mdown = e.type == ButtonPress; if (tb_mdown) tb_mtap = 1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v7085; }
    { const char * tb_v7086 = "            if (e.xbutton.button == 8 || e.xbutton.button == 9) tb_side(e.xbutton.button - 8, e.type == ButtonPress);\n"; *(const char * *)tb_grow(v_lines) = tb_v7086; }
    { const char * tb_v7087 = "            if (e.type == ButtonPress && e.xbutton.button == 4) tb_wheel_add(1);\n"; *(const char * *)tb_grow(v_lines) = tb_v7087; }
