    { const char * tb_v7097 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v7097; }
    { const char * tb_v7098 = "// TB_GPU_CHECK: проба смешивания. Видеокарты считают смешивание по-своему (AMD на Mac — с малой\n"; *(const char * *)tb_grow(v_lines) = tb_v7098; }
    { const char * tb_v7099 = "// точностью, ошибка зависит и от цвета буквы, и от фона), поэтому проба берёт все сочетания:\n"; *(const char * *)tb_grow(v_lines) = tb_v7099; }
    { const char * tb_v7100 = "// цвет c, фон d, прозрачность a — 256 × 256 × 256 точек, кадр за кадром, и процессор дальше\n"; *(const char * *)tb_grow(v_lines) = tb_v7100; }
    { const char * tb_v7101 = "// смешивает по этой таблице (tb_blend_lut[c][d][a]). Делается один раз, когда есть и окно, и шрифт.\n"; *(const char * *)tb_grow(v_lines) = tb_v7101; }
    { const char * tb_v7102 = "// После пробы кадр видеокарты снова становится таким же, как у процессора (копия tb_px)\n"; *(const char * *)tb_grow(v_lines) = tb_v7102; }
    { const char * tb_v7103 = "TB_API void tb_gpu_blend_probe(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7103; }
    { const char * tb_v7104 = "    if (!tb_gpu_on || !tb_gpu_check || tb_blend_cal || !tb_px || !tb_nfonts) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v7104; }
    { const char * tb_v7105 = "    uint8_t *lut = malloc((size_t)1 << 24);\n"; *(const char * *)tb_grow(v_lines) = tb_v7105; }
    { const char * tb_v7106 = "    if (!lut) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v7106; }
    { const char * tb_v7107 = "    size_t n = (size_t)tb_gw * tb_gh, p0 = tb_imgpx_n, need = p0 + 3 * n;\n"; *(const char * *)tb_grow(v_lines) = tb_v7107; }
    { const char * tb_v7108 = "    int n0 = tb_nimg;\n"; *(const char * *)tb_grow(v_lines) = tb_v7108; }
    { const char * tb_v7109 = "    uint32_t *all = need <= 0xFFFFFFFFu ? realloc(tb_imgpx, need * 4) : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7109; }
    { const char * tb_v7110 = "    tb_image *list = realloc(tb_imgs, (size_t)(n0 + 3) * sizeof(tb_image));\n"; *(const char * *)tb_grow(v_lines) = tb_v7110; }
    { const char * tb_v7111 = "    if (all) tb_imgpx = all;\n"; *(const char * *)tb_grow(v_lines) = tb_v7111; }
    { const char * tb_v7112 = "    if (list) tb_imgs = list;\n"; *(const char * *)tb_grow(v_lines) = tb_v7112; }
    { const char * tb_v7113 = "    if (!all || !list) { free(lut); return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v7113; }
    { const char * tb_v7114 = "    for (int k = 0; k < 3; k++) { tb_imgs[n0 + k].w = tb_gw; tb_imgs[n0 + k].h = tb_gh; tb_imgs[n0 + k].off = (uint32_t)(p0 + k * n); }\n"; *(const char * *)tb_grow(v_lines) = tb_v7114; }
    { const char * tb_v7115 = "    tb_nimg = n0 + 3; tb_imgpx_n = need;\n"; *(const char * *)tb_grow(v_lines) = tb_v7115; }
    { const char * tb_v7116 = "    uint32_t *keep = tb_imgpx + p0 + 2 * n;   // кадр процессора: вернуть его видеокарте после пробы\n"; *(const char * *)tb_grow(v_lines) = tb_v7116; }
    { const char * tb_v7117 = "    for (size_t q = 0; q < n; q++) keep[q] = 0xFF000000u | tb_px[q];\n"; *(const char * *)tb_grow(v_lines) = tb_v7117; }
    { const char * tb_v7118 = "    tb_gpu_probing = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v7118; }
    { const char * tb_v7119 = "    int ok = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v7119; }
    { const char * tb_v7120 = "    for (size_t from = 0; from < ((size_t)1 << 24) && ok; from += n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7120; }
    { const char * tb_v7121 = "        uint32_t *bg = tb_imgpx + p0, *fg = bg + n;\n"; *(const char * *)tb_grow(v_lines) = tb_v7121; }
    { const char * tb_v7122 = "        for (size_t q = 0; q < n; q++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7122; }
    { const char * tb_v7123 = "            size_t i = (from + q) & 0xFFFFFF;\n"; *(const char * *)tb_grow(v_lines) = tb_v7123; }
    { const char * tb_v7124 = "            uint32_t c = (uint32_t)(i >> 16), d = (uint32_t)(i >> 8) & 255, a = (uint32_t)i & 255;\n"; *(const char * *)tb_grow(v_lines) = tb_v7124; }
    { const char * tb_v7125 = "            bg[q] = 0xFF000000u | d * 0x010101u;\n"; *(const char * *)tb_grow(v_lines) = tb_v7125; }
    { const char * tb_v7126 = "            fg[q] = (a << 24) | c * 0x010101u;\n"; *(const char * *)tb_grow(v_lines) = tb_v7126; }
    { const char * tb_v7127 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v7127; }
    { const char * tb_v7128 = "        tb_img_dirty = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v7128; }
    { const char * tb_v7129 = "        tb_gpu_image(n0, 0, 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v7129; }
    { const char * tb_v7130 = "        tb_gpu_image_a(n0 + 1, 0, 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v7130; }
    { const char * tb_v7131 = "        tb_gpu_flush(1);\n"; *(const char * *)tb_grow(v_lines) = tb_v7131; }
    { const char * tb_v7132 = "        if (!tb_gpu_back) { ok = 0; break; }\n"; *(const char * *)tb_grow(v_lines) = tb_v7132; }
    { const char * tb_v7133 = "        for (size_t q = 0; q < n && from + q < ((size_t)1 << 24); q++) lut[from + q] = (uint8_t)(tb_gpu_back[q] & 255);\n"; *(const char * *)tb_grow(v_lines) = tb_v7133; }
    { const char * tb_v7134 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v7134; }
    { const char * tb_v7135 = "    tb_gpu_image(n0 + 2, 0, 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v7135; }
    { const char * tb_v7136 = "    tb_gpu_flush(1);\n"; *(const char * *)tb_grow(v_lines) = tb_v7136; }
    { const char * tb_v7137 = "    tb_gpu_probing = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7137; }
    { const char * tb_v7138 = "    tb_nimg = n0; tb_imgpx_n = p0; tb_img_dirty = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v7138; }
    { const char * tb_v7139 = "    if (!ok) { free(lut); return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v7139; }
    { const char * tb_v7140 = "    tb_blend_lut = lut;\n"; *(const char * *)tb_grow(v_lines) = tb_v7140; }
    { const char * tb_v7141 = "    tb_blend_cal = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v7141; }
    { const char * tb_v7142 = "    const char *e = getenv(\"TB_GPU_INFO\");\n"; *(const char * *)tb_grow(v_lines) = tb_v7142; }
    { const char * tb_v7143 = "    if (e && e[0] == '1') {\n"; *(const char * *)tb_grow(v_lines) = tb_v7143; }
    { const char * tb_v7144 = "        long long diff = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7144; }
    { const char * tb_v7145 = "        for (size_t i = 0; i < ((size_t)1 << 24); i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7145; }
    { const char * tb_v7146 = "            uint32_t c = (uint32_t)(i >> 16), d = (uint32_t)(i >> 8) & 255, a = (uint32_t)i & 255;\n"; *(const char * *)tb_grow(v_lines) = tb_v7146; }
    { const char * tb_v7147 = "            uint32_t w = a == 0 ? d : (c * a + 127) / 255 + (d * (255 - a) + 127) / 255;\n"; *(const char * *)tb_grow(v_lines) = tb_v7147; }
    { const char * tb_v7148 = "            diff += lut[i] != w;\n"; *(const char * *)tb_grow(v_lines) = tb_v7148; }
    { const char * tb_v7149 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v7149; }
    { const char * tb_v7150 = "        fprintf(stderr, \"TB_GPU_CHECK: смешивание на этой видеокарте не как округление к ближайшему: %lld из %d\\n\", diff, 1 << 24);\n"; *(const char * *)tb_grow(v_lines) = tb_v7150; }
    { const char * tb_v7151 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v7151; }
    { const char * tb_v7152 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7152; }
    { const char * tb_v7153 = "// window_sharp(): окно в настоящих точках экрана (Retina, 150% и 200% на Windows). Размер в window_open\n"; *(const char * *)tb_grow(v_lines) = tb_v7153; }
    { const char * tb_v7154 = "// остаётся в «обычных» точках, а кадр, window_w/h и мышь — в настоящих; window_scale() — во сколько раз\n"; *(const char * *)tb_grow(v_lines) = tb_v7154; }
    { const char * tb_v7155 = "TB_API double tb_gfx_scale(void);   // своя у каждой системы\n"; *(const char * *)tb_grow(v_lines) = tb_v7155; }
    { const char * tb_v7156 = "TB_API void tb_window_sharp(void) { if (!tb_px) tb_sharp = 1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v7156; }
    { const char * tb_v7157 = "TB_API double tb_window_scale(void) { return tb_sc; }\n"; *(const char * *)tb_grow(v_lines) = tb_v7157; }
    { const char * tb_v7158 = "TB_API void tb_window_open(long long w, long long h, const char *title) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7158; }
    { const char * tb_v7159 = "    if (tb_px) { tb_err = \"окно уже открыто\"; return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v7159; }
    { const char * tb_v7160 = "    if (w < 1 || h < 1 || w > 8192 || h > 8192) { tb_err = \"размер окна от 1 до 8192\"; return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v7160; }
    { const char * tb_v7161 = "    if (tb_sharp) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7161; }
    { const char * tb_v7162 = "        tb_sc = tb_gfx_scale();\n"; *(const char * *)tb_grow(v_lines) = tb_v7162; }
    { const char * tb_v7163 = "        if (tb_sc < 1) tb_sc = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v7163; }
    { const char * tb_v7164 = "        if (tb_sc > 4) tb_sc = 4;\n"; *(const char * *)tb_grow(v_lines) = tb_v7164; }
    { const char * tb_v7165 = "        w = (long long)(w * tb_sc + 0.5); h = (long long)(h * tb_sc + 0.5);\n"; *(const char * *)tb_grow(v_lines) = tb_v7165; }
    { const char * tb_v7166 = "        if (w > 8192) w = 8192;\n"; *(const char * *)tb_grow(v_lines) = tb_v7166; }
    { const char * tb_v7167 = "        if (h > 8192) h = 8192;\n"; *(const char * *)tb_grow(v_lines) = tb_v7167; }
    { const char * tb_v7168 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v7168; }
    { const char * tb_v7169 = "    tb_gw = (int)w; tb_gh = (int)h;\n"; *(const char * *)tb_grow(v_lines) = tb_v7169; }
    { const char * tb_v7170 = "    tb_px = calloc((size_t)tb_gw * tb_gh, 4);\n"; *(const char * *)tb_grow(v_lines) = tb_v7170; }
    { const char * tb_v7171 = "    if (!tb_gfx_open(title)) { free(tb_px); tb_px = 0; tb_err = \"не могу открыть окно: нет экрана\"; return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v7171; }
    { const char * tb_v7172 = "    if (tb_gpu_on && tb_gpu_check) { atexit(tb_gpu_report); tb_gpu_blend_probe(); }\n"; *(const char * *)tb_grow(v_lines) = tb_v7172; }
    { const char * tb_v7173 = "    tb_last_frame = tb_time_ms();\n"; *(const char * *)tb_grow(v_lines) = tb_v7173; }
    { const char * tb_v7174 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7174; }
    { const char * tb_v7175 = "// показать кадр, принять клавиши и мышь, держать 60 кадров в секунду; false — окно закрыли\n"; *(const char * *)tb_grow(v_lines) = tb_v7175; }
    { const char * tb_v7176 = "// окно поменяло размер: новый кадр, старое остаётся в левом верхнем углу, новое место — чёрное\n"; *(const char * *)tb_grow(v_lines) = tb_v7176; }
    { const char * tb_v7177 = "TB_API void tb_apply_resize(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7177; }
    { const char * tb_v7178 = "    if (!tb_new_w) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v7178; }
    { const char * tb_v7179 = "    int nw = tb_new_w > 8192 ? 8192 : tb_new_w, nh = tb_new_h > 8192 ? 8192 : tb_new_h, ow = tb_gw, oh = tb_gh;\n"; *(const char * *)tb_grow(v_lines) = tb_v7179; }
    { const char * tb_v7180 = "    tb_new_w = tb_new_h = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7180; }
    { const char * tb_v7181 = "    if (nw < 1 || nh < 1 || (nw == ow && nh == oh)) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v7181; }
    { const char * tb_v7182 = "    uint32_t *np = calloc((size_t)nw * nh, 4);\n"; *(const char * *)tb_grow(v_lines) = tb_v7182; }
    { const char * tb_v7183 = "    if (!np) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v7183; }
    { const char * tb_v7184 = "    for (int y = 0; y < oh && y < nh; y++) memcpy(np + (size_t)y * nw, tb_px + (size_t)y * ow, (size_t)(ow < nw ? ow : nw) * 4);\n"; *(const char * *)tb_grow(v_lines) = tb_v7184; }
    { const char * tb_v7185 = "    free(tb_px);\n"; *(const char * *)tb_grow(v_lines) = tb_v7185; }
    { const char * tb_v7186 = "    tb_px = np; tb_gw = nw; tb_gh = nh;\n"; *(const char * *)tb_grow(v_lines) = tb_v7186; }
    { const char * tb_v7187 = "    tb_gfx_reimage();\n"; *(const char * *)tb_grow(v_lines) = tb_v7187; }
    { const char * tb_v7188 = "    if (tb_gpu_on && !tb_gpu_resize(ow, oh)) fprintf(stderr, \"видеокарта: не получилось поменять размер кадра\\n\");\n"; *(const char * *)tb_grow(v_lines) = tb_v7188; }
    { const char * tb_v7189 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7189; }
