    { const char * tb_v7253 = "TB_API void tb_draw_circle(long long cx, long long cy, long long r, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7253; }
    { const char * tb_v7254 = "    if (!tb_px) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v7254; }
