    { const char * tb_v7256 = "    if (TB_CPU_DRAW) {   // только строки и столбцы внутри окна: огромный круг не перебирает r*r точек\n"; *(const char * *)tb_grow(v_lines) = tb_v7256; }
    { const char * tb_v7257 = "        long long ja = -r > -cy ? -r : -cy, jb = r < tb_gh - 1 - cy ? r : tb_gh - 1 - cy;\n"; *(const char * *)tb_grow(v_lines) = tb_v7257; }
    { const char * tb_v7258 = "        long long ia = -r > -cx ? -r : -cx, ib = r < tb_gw - 1 - cx ? r : tb_gw - 1 - cx;\n"; *(const char * *)tb_grow(v_lines) = tb_v7258; }
    { const char * tb_v7259 = "        for (long long j = ja; j <= jb; j++) for (long long i = ia; i <= ib; i++)\n"; *(const char * *)tb_grow(v_lines) = tb_v7259; }
    { const char * tb_v7260 = "            if (i * i + j * j <= r * r + r) tb_put(cx + i, cy + j, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v7260; }
