    { const char * tb_v7272 = "        long long e2 = 2 * e;\n"; *(const char * *)tb_grow(v_lines) = tb_v7272; }
    { const char * tb_v7273 = "        if (e2 >= dy) { e += dy; x0 += sx; }\n"; *(const char * *)tb_grow(v_lines) = tb_v7273; }
    { const char * tb_v7274 = "        if (e2 <= dx) { e += dx; y0 += sy; }\n"; *(const char * *)tb_grow(v_lines) = tb_v7274; }
