    { const char * tb_v7634 = "            } else tb_poly_draw(sx, sy, 3, m->c[t], pl);\n"; *(const char * *)tb_grow(v_lines) = tb_v7634; }
    { const char * tb_v7635 = "            continue;\n"; *(const char * *)tb_grow(v_lines) = tb_v7635; }
