    { const char * tb_v7646 = "                qx[n] = p->cx + (q->cx - p->cx) * k; qy[n] = p->cy + (q->cy - p->cy) * k; qz[n] = zn; n++;\n"; *(const char * *)tb_grow(v_lines) = tb_v7646; }
    { const char * tb_v7647 = "            }\n"; *(const char * *)tb_grow(v_lines) = tb_v7647; }
    { const char * tb_v7648 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v7648; }
    { const char * tb_v7649 = "        if (n < 3) continue;\n"; *(const char * *)tb_grow(v_lines) = tb_v7649; }
