    { const char * tb_v7752 = "    if (cc[2] + rad < 205.0 / 4096) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7752; }
    { const char * tb_v7753 = "    double hw = tb_gw / 2.0 + 2, hh = tb_gh / 2.0 + 2, lx = sqrt(f * f + hw * hw), ly = sqrt(f * f + hh * hh);\n"; *(const char * *)tb_grow(v_lines) = tb_v7753; }
    { const char * tb_v7754 = "    if ((f * cc[0] - hw * cc[2]) / lx > rad || (-f * cc[0] - hw * cc[2]) / lx > rad) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7754; }
