    { const char * tb_v8394 = "// тон: синус hz герц на ms миллисекунд, мягкое начало и конец (без щелчков)\n"; *(const char * *)tb_grow(v_lines) = tb_v8394; }
    { const char * tb_v8395 = "TB_API long long tb_play_tone(double hz, long long ms) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8395; }
    { const char * tb_v8396 = "    if (ms <= 0 || hz <= 0) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8396; }
    { const char * tb_v8397 = "    if (ms > 60000) ms = 60000;\n"; *(const char * *)tb_grow(v_lines) = tb_v8397; }
    { const char * tb_v8398 = "    long long n = ms * TB_SR / 1000;\n"; *(const char * *)tb_grow(v_lines) = tb_v8398; }
    { const char * tb_v8399 = "    float *d = malloc(sizeof(float) * (size_t)(n + 1));\n"; *(const char * *)tb_grow(v_lines) = tb_v8399; }
    { const char * tb_v8400 = "    if (!d) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8400; }
    { const char * tb_v8401 = "    long long ramp = TB_SR / 200;\n"; *(const char * *)tb_grow(v_lines) = tb_v8401; }
    { const char * tb_v8402 = "    if (ramp * 2 > n) ramp = n / 2;\n"; *(const char * *)tb_grow(v_lines) = tb_v8402; }
    { const char * tb_v8403 = "    for (long long i = 0; i < n; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8403; }
    { const char * tb_v8404 = "        double e = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v8404; }
    { const char * tb_v8405 = "        if (i < ramp) e = (double)i / ramp;\n"; *(const char * *)tb_grow(v_lines) = tb_v8405; }
    { const char * tb_v8406 = "        else if (i >= n - ramp) e = (double)(n - 1 - i) / ramp;\n"; *(const char * *)tb_grow(v_lines) = tb_v8406; }
    { const char * tb_v8407 = "        d[i] = (float)(0.5 * e * sin(6.283185307179586 * hz * (double)i / TB_SR));\n"; *(const char * *)tb_grow(v_lines) = tb_v8407; }
    { const char * tb_v8408 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v8408; }
    { const char * tb_v8409 = "    long long s = tb_snd_add(d, n, 1, TB_SR, 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v8409; }
    { const char * tb_v8410 = "    if (s < 0) { free(d); return 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v8410; }
    { const char * tb_v8411 = "    long long v = tb_voice_new(s, 0, 0, 0, 0, 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v8411; }
    { const char * tb_v8412 = "    if (v == 0) { pthread_mutex_lock(&tb_slock); free(tb_snds[s].d); tb_snds[s].d = 0; pthread_mutex_unlock(&tb_slock); }\n"; *(const char * *)tb_grow(v_lines) = tb_v8412; }
    { const char * tb_v8413 = "    return v;\n"; *(const char * *)tb_grow(v_lines) = tb_v8413; }
    { const char * tb_v8414 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v8414; }
