    { const char * tb_v8456 = "// слушатель: где уши и куда смотрит (как camera; вверх — ось y)\n"; *(const char * *)tb_grow(v_lines) = tb_v8456; }
    { const char * tb_v8457 = "TB_API void tb_listener(double x, double y, double z, double lx, double ly, double lz) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8457; }
    { const char * tb_v8458 = "    double f[3] = { lx - x, ly - y, lz - z }, l = sqrt(f[0] * f[0] + f[1] * f[1] + f[2] * f[2]);\n"; *(const char * *)tb_grow(v_lines) = tb_v8458; }
